// __ASTRO_PRINT_BEGIN__ (injection saut de page, sûr)
const __ASTRO_PRINT_CSS = `<style id="astro-print-rules">/* ASTRO-PRINT-RULES */
@media print {
  /* --- Règles SÛRES, génériques, valables sur tous les rapports --- */

  /* Lignes de tableau jamais coupées + en-tête répété sur chaque page.
     (On agit au niveau TR, pas TABLE : un grand tableau de données peut donc
     s'étaler sur plusieurs pages sans qu'une ligne soit coupée ni déborder.) */
  tr { break-inside: avoid; page-break-inside: avoid; }
  thead { display: table-header-group; }
  tfoot { display: table-footer-group; }

  /* Un vrai titre reste collé au contenu qui suit, et ne se coupe pas. */
  h1, h2, h3, h4, h5, h6 { break-after: avoid; page-break-after: avoid; break-inside: avoid; page-break-inside: avoid; }

  /* Médias / figures insécables. */
  img, svg, figure { break-inside: avoid; page-break-inside: avoid; }

  /* Pas de ligne veuve/orpheline isolée. */
  p, li { orphans: 3; widows: 3; }

  /* --- Crochets de classe : protègent les petits blocs marqués comme atomiques.
     Sans risque : si la classe n'existe pas dans un rapport, la règle est inerte.
     (Récit : .chap-head/.chap-intro/.break-avoid ; autres rapports : ajoutés au besoin.) --- */
  .break-avoid, .keep-together, .chap-head, .chap-intro,
  .reperes-card, .paran-card, .chip-card {
    break-inside: avoid; page-break-inside: avoid;
  }
  .chap-head, .chap-intro, .keep-together { break-after: avoid; page-break-after: avoid; }

  /* Cartouche d'en-tête de section (bandeau bleu) : reste collée à son contenu,
     jamais seule en bas de page. Cible le 1er enfant des conteneurs de section
     (.house-section, .recit-chapter, *-section…), sans toucher au reste du bloc. */
  .recit-chapter > div:first-child,
  [class$="-section"] > div:first-child,
  [class*="-section "] > div:first-child {
    break-after: avoid; page-break-after: avoid; break-inside: avoid; page-break-inside: avoid;
  }

  /* --- Récit : cartouches en styles INLINE (sans classe). On les cible par leur
     style caractéristique pour les rendre insécables. Inerte ailleurs. --- */
  /* Bandeau d'en-tête bleu marine : ne se coupe pas et reste collé à ce qui suit. */
  div[style*="background:#2E5FA3"],
  div[style*="background: #2E5FA3"],
  div[style*="background:#1F3864"],
  div[style*="background: #1F3864"] {
    break-inside: avoid; page-break-inside: avoid;
    break-after: avoid; page-break-after: avoid;
  }
  /* Cartouche d'intro italique (liseré gauche) : bloc atomique, jamais coupé. */
  div[style*="border-left:4px solid #2E5FA3"],
  div[style*="border-left: 4px solid #2E5FA3"],
  div[style*="border-left:3px solid"],
  div[style*="border-left:4px solid"] {
    break-inside: avoid; page-break-inside: avoid;
  }
}
</style>`;
function __inject(h){ try { if (typeof h !== 'string' || h.indexOf('astro-print-rules') !== -1) return h; if (/<\/head>/i.test(h)) return h.replace(/<\/head>/i, __ASTRO_PRINT_CSS + '</head>'); if (/<body[^>]*>/i.test(h)) return h.replace(/(<body[^>]*>)/i, '$1' + __ASTRO_PRINT_CSS); return __ASTRO_PRINT_CSS + h; } catch(e){ return h; } }
