function buildWheelLegendSyn(en) {
  const poss = en ? { m: 'Your', f: 'Your', p: 'Your' } : { m: 'Votre', f: 'Votre', p: 'Vos' };
  const lead = (cls) => cls === 'kw' ? '' : poss[cls] + ' ';
  const planetItems = PLANET_LEGEND.map(p => {
    const name = en ? p.en : p.fr;
    const d = en ? p.den : p.dfr;
    const fn = p.cls === 'kw' ? d : lead(p.cls) + d;
    return `<div class="legend-item legend-item--fn"><span class="legend-glyph">${p.g}</span><span class="legend-text"><span class="legend-name">${name}</span><span class="legend-fn">${fn}</span></span></div>`;
  }).join('');
  const angleItems = ANGLE_LEGEND.map(a => {
    const name = en ? a.en : a.fr;
    const d = en ? a.den : a.dfr;
    return `<div class="legend-item legend-item--fn"><span class="legend-text"><span class="legend-name"><strong>${a.ab}</strong> — ${name}</span><span class="legend-fn">${lead(a.cls)}${d}</span></span></div>`;
  }).join('');
  const houseRows = HOUSE_LEGEND.map(h => `<div class="legend-item legend-item--fn"><span class="legend-text"><span class="legend-name"><strong>${en ? 'H' : 'M'}${h.n}</strong> — ${en ? h.en : h.fr}</span></span></div>`).join('');
