        <div><div class="legend-title">${en ? 'Planets and Objects' : 'Planètes et Objets'}</div>${planetItems}</div>
        <div><div class="legend-title">${en ? 'Zodiac Signs' : 'Signes du Zodiaque'}</div>${signItems}</div>
        <div><div class="legend-title">${en ? 'Houses and Angles' : 'Maisons et Angles'}</div>${angleItems}<div class="legend-house-sep"></div>${houseRows}</div>
    </div>`;
}

