    /* ===== TOKENS SPIKKA (changer la palette ici = tout le rapport) ===== */
    :root{
        --bg-report:#FFFFFF; --bg-hero:#2E1560; --primary:#2E1560; --accent:#FFA6F6;
        --ink:#2A2342; --ink-soft:#7A7393; --hero-text:#FFFFFF; --hero-soft:#C9B6F0;
        --line:rgba(46,21,96,0.12); --grid:rgba(46,21,96,0.045);
        --font-title:'Shrikhand', Georgia, serif; --font-body:'Montserrat','Segoe UI', sans-serif;
