        --radius:16px; --person-a:#2E1560; --person-b:#C7359E;
    }
    * { box-sizing: border-box; }
    body { font-family: var(--font-body); background: var(--bg-report); color: var(--ink); padding: 0; font-size: 14.5px; line-height: 1.7;
        -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .container { max-width: 840px; margin: 0 auto; background-color: var(--bg-report);
        background-image: linear-gradient(to right, var(--grid) 1px, transparent 1px), linear-gradient(to bottom, var(--grid) 1px, transparent 1px);
        background-size: 42px 42px; padding: 0 14px 40px; border-radius: 0; box-shadow: none;
        -webkit-print-color-adjust: exact; print-color-adjust: exact; }

    /* ===== Couverture héros (repris À LA LETTRE du rapport refondu — synastrie 2 personnes) ===== */
    .sk-cover{ box-sizing:border-box; background:var(--bg-hero); color:var(--hero-text); border-radius:var(--radius); min-height:860px; margin:8px 0 0; padding:46px; display:flex; flex-direction:column; justify-content:space-between; -webkit-print-color-adjust:exact; print-color-adjust:exact; break-inside:avoid; }
    .sk-cover *,.sk-toc-hero *{ box-sizing:border-box; }
    .sk-cover-top{ display:flex; justify-content:flex-end; }
    .sk-cover-logo{ width:128px; height:128px; border-radius:50%; object-fit:cover; border:3px solid var(--accent); background:#fff; -webkit-print-color-adjust:exact; print-color-adjust:exact; display:block; }
    .sk-cover-mid{ margin:auto 0; }
    .sk-cover-eyebrow{ font-family:var(--font-body); font-weight:600; letter-spacing:5px; text-transform:uppercase; font-size:13px; color:var(--hero-soft); margin-bottom:22px; }
    .sk-cover-name{ font-family:var(--font-title); font-size:64px; line-height:1.04; color:#fff; }
    .sk-cover-amp{ font-family:var(--font-title); font-size:40px; color:var(--accent); line-height:1.1; margin:2px 0; }
    .sk-cover-nameb{ font-family:var(--font-title); font-size:64px; line-height:1.04; color:var(--accent); }
    .sk-cover-lum{ margin-top:30px; font-size:15px; font-weight:500; letter-spacing:1px; color:var(--hero-soft); }
    .sk-cover-foot{ font-size:13px; letter-spacing:2px; text-transform:uppercase; color:var(--hero-soft); border-top:1px solid rgba(255,255,255,0.18); padding-top:18px; }
    /* Sommaire héros (repris À LA LETTRE du rapport refondu) */
    .sk-toc-hero{ box-sizing:border-box; background:var(--bg-hero); color:var(--hero-text); border-radius:var(--radius); min-height:800px; margin:8px 0 0; padding:38px 50px; display:flex; flex-direction:column; justify-content:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; break-inside:avoid; }
    .sk-toc-title{ font-family:var(--font-title); font-size:46px; line-height:0.98; color:#fff; margin:0 0 14px; }
    .sk-toc-ul{ list-style:none; padding:0; margin:0; }
    .sk-toc-a{ display:flex; align-items:baseline; gap:14px; padding:2px 2px; text-decoration:none; color:#fff; }
    .sk-toc-num{ font-family:var(--font-title); font-size:15px; color:var(--accent); min-width:30px; flex-shrink:0; }
    .sk-toc-lab{ font-family:var(--font-title); font-size:16px; color:#fff; line-height:1.15; }

    /* ===== En-tête de section éditorial (repris À LA LETTRE du SYN technique : numéro rose + titre violet + sous-titre + filet rose) ===== */
    h2.section-title { display: flex !important; align-items: center !important; gap: 14px !important; background: none !important; color: var(--primary) !important; font-family: var(--font-title) !important; font-size: 26px !important; font-weight: 400 !important; padding: 0 !important; border: none !important; border-radius: 0 !important; text-align: left !important; margin: 42px 0 18px !important; letter-spacing: 0 !important; line-height: 1.05 !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    h2.section-title .sk-secno { font-family: var(--font-title); color: var(--accent); font-size: 30px; line-height: 1; flex-shrink: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    h2.section-title .sk-section-tt { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
    h2.section-title .sk-section-h { font-family: var(--font-title); font-size: 26px; color: var(--primary); line-height: 1.05; }
    h2.section-title .sk-section-sub { font-family: var(--font-body); font-weight: 500; font-size: 13px; letter-spacing: .3px; color: var(--ink-soft); line-height: 1.3; text-transform: none; }
    h2.section-title .fiabilite-badge { flex-shrink:0; align-self:center; }
    h2.section-title::after { content: ""; flex: 1; height: 2px; background: var(--accent); border-radius: 2px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    /* Titres de colonnes de légende : pastille violette pleine (parité SYN technique) */
    .legend-col-title { background: var(--primary); color: #fff; font-family: var(--font-title); font-size: 16px; font-weight: 400; padding: 0 16px; border-radius: 10px; display: flex; align-items: center; justify-content: center; text-align: center; min-height: 42px; margin: 0 0 14px; letter-spacing: 0.2px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    /* Légende riche de la roue (parité buildWheelLegend SYN technique) */
    .legend-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px; margin-top: 0; text-align: left; font-size: 0.92em; padding-top: 0; }
    .legend-item { display: flex; align-items: center; gap: 7px; margin-bottom: 6px; white-space: normal; overflow-wrap: break-word; color: var(--ink); line-height: 1.35; }
    .legend-item--fn { align-items: flex-start; margin-bottom: 8px; }
    .legend-item--fn .legend-glyph { line-height: 1.1; }
    .legend-text { display: flex; flex-direction: column; min-width: 0; }
    .legend-name { line-height: 1.2; }
    .legend-fn { font-size: 0.78em; color: var(--ink-soft); font-weight: 400; line-height: 1.2; margin-top: 1px; }
    .legend-glyph { font-size: 1.4em; width: 25px; text-align: center; font-weight: bold; color: var(--primary); font-family: 'Noto Sans Symbols 2','Segoe UI Symbol','Apple Symbols','Symbola','Arial Unicode MS', sans-serif; }
    .legend-house-sep { border-bottom: 1px solid var(--line); margin: 12px 0; }
    .legend-title { background: var(--primary) !important; color: #fff !important; font-family: var(--font-title) !important; font-size: 1.15em !important; font-weight: 400 !important; padding: 0 15px !important; border-radius: 10px !important; display: flex !important; align-items: center !important; justify-content: center !important; text-align: center !important; margin: 0 0 15px 0 !important; min-height: 44px !important; letter-spacing: 0.2px !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    /* Conteneur de roue bordé (parité .sk-wheel SYN technique) */
    .wheel-container { background: #fff; border: 1px solid var(--line); border-radius: var(--radius); padding: 12px; box-shadow: 0 4px 18px rgba(46,21,96,0.03); }
    .sk-card { background: #fff; border: 1px solid var(--line); border-radius: var(--radius); padding: 22px 24px; margin-bottom: 22px; box-shadow: 0 4px 18px rgba(46,21,96,0.03); }
    /* Empreinte élémentaire — PORT EXACT du rapport FINAL SYN (cartes + pictos SVG) */
    .sk-badge{flex-shrink:0;width:44px;height:44px;border-radius:50%;background:rgba(255,166,246,0.14);border:1.5px solid var(--accent);color:var(--primary);display:flex;align-items:center;justify-content:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
    .sk-badge svg{width:22px;height:22px;display:block;}
    .sk-badge--txt{font-family:var(--font-title);font-size:15px;font-weight:700;letter-spacing:.5px;}
    .syn-empreinte-wrap{margin:4px 0 6px;}
    .syn-empreinte{margin:0 0 12px;break-inside:avoid;page-break-inside:avoid;}
    .syn-empreinte .sk-reperes{padding:14px 16px;margin-bottom:0;}
    .syn-empreinte-who{display:flex;align-items:center;gap:8px;font-weight:700;font-size:14px;margin:0 0 9px 2px;}
    .syn-empreinte-dot{display:inline-block;width:13px;height:13px;border-radius:50%;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
    .sk-big3-row{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;}
    .sk-big3{border:1px solid var(--line);border-radius:11px;padding:9px 8px;text-align:center;}
    .sk-big3-lab{font-size:9.5px;letter-spacing:1px;text-transform:uppercase;color:var(--ink-soft);}
    .sk-big3-val{font-family:var(--font-title);font-size:16px;color:var(--primary);margin-top:2px;}
    .sk-big3 .sk-badge{width:34px;height:34px;margin:0 auto 4px;}
    .sk-big3 .sk-badge svg{width:17px;height:17px;}
    .syn-empreinte .sk-badge--txt{font-family:var(--font-body);font-weight:600;font-size:13px;letter-spacing:.5px;color:var(--primary);}
    .sk-elem-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:9px;}
    .sk-elem{border:1px solid var(--line);border-radius:11px;padding:9px 4px;text-align:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
    .sk-elem-dom{border:2px solid var(--ec);}
    .sk-elem-tri{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:50%;background:var(--ecbg);border:1.5px solid var(--ec);color:var(--ec);margin:0 auto 5px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
    .sk-elem-tri svg{width:18px;height:18px;display:block;}
    .sk-elem-name{font-weight:700;color:var(--ec);font-size:13px;}
    .sk-elem-n{font-size:18px;font-weight:700;margin:3px 0;color:var(--ink);}
