    .sk-elem-badge{display:inline-block;margin-top:5px;padding:2px 8px;border-radius:6px;font-size:9.5px;font-weight:700;background:var(--ec);color:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
    .sk-bar{display:flex;height:11px;border-radius:7px;overflow:hidden;margin-top:10px;border:1px solid var(--line);}
    .syn-empreinte, .sk-reperes, .sk-big3, .sk-elem, .sk-big3-row, .sk-elem-grid { break-inside: avoid; page-break-inside: avoid; }
    .aspects-bar { padding: 12px 18px; background: #fff; border: 1px solid var(--line); border-radius: 12px; display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; align-items: center; margin-bottom: 14px; box-shadow: 0 4px 18px rgba(46,21,96,0.03); -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    /* En-têtes de cartes : bandeaux pleins violets */
    .stat-card-header { background: var(--primary) !important; color: #fff !important; font-family: var(--font-title) !important; font-size: 16px !important; font-weight: 400 !important; padding: 0 16px !important; border-radius: 10px 10px 0 0 !important; display: flex !important; align-items: center !important; justify-content: center !important; text-align: center !important; margin: 0 !important; min-height: 44px !important; letter-spacing: 0.2px !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .subsection-title { background: rgba(255,166,246,0.16) !important; color: var(--primary) !important; font-family: var(--font-body) !important; font-size: 13px !important; font-weight: 700 !important; text-transform: uppercase; letter-spacing: 0.5px; padding: 8px 14px !important; border: none !important; border-left: 3px solid var(--accent) !important; border-radius: 0 8px 8px 0 !important; margin: 24px 0 10px !important; display: block !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    h3.sub-direction { font-family: var(--font-title); font-size: 1.05em; font-weight: 400; margin: 20px 0 8px; padding: 9px 15px; border-radius: 8px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    h3.sub-direction.dir-a { background: var(--person-a); color: white; }
