    .tag-variant { display: inline-block; background: rgba(46,21,96,0.06); color: var(--primary); font-size: 0.7em; font-weight: 600; border-radius: 20px; padding: 1px 8px; margin-left: 6px; vertical-align: middle; }
    .score-badge { font-size: 0.74em; padding: 3px 9px; border-radius: 20px; font-weight: 700; margin-left: 8px; display: inline-block; vertical-align: middle; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .score-absolu { background: var(--primary); color: #fff; }
