                    <td>${statutCell}</td>
                    <td style="font-size:0.85em">${paraCell}</td>
                </tr>`;
            });
            s += `</tbody></table></div>`;
            return s;
        }
        html += renderDeclTable(declPlaA, `${prenomA} ${nomA}`, 'dir-a');
