            html += `<table><colgroup><col style="width:12%"><col style="width:12%"><col style="width:11%"><col style="width:8%"><col style="width:12%"><col style="width:12%"><col style="width:11%"><col style="width:7%"><col style="width:15%"></colgroup>
                <thead><tr><th>P1</th><th style="text-align:center">${isEN ? 'Decl.1' : 'Décl.1'}</th><th>${isEN ? 'Pers.' : 'Pers.'}</th><th style="text-align:center">${isEN ? 'Hem.' : 'Hém.'}</th><th>P2</th><th style="text-align:center">${isEN ? 'Decl.2' : 'Décl.2'}</th><th>Pers.</th><th style="text-align:center">${isEN ? 'Orb' : 'Orbe'}</th><th>Note</th></tr></thead><tbody>`;
