        dignities.forEach(d => {
            const color = d.score >= 15 ? '#166534' : d.score >= 8 ? '#1e40af' : d.score >= 0 ? '#475569' : '#991b1b';
            const ess = d.essential_score != null ? d.essential_score : '—';
