                    <td style="text-align:center">${ec.orb}°</td>
                    <td style="text-align:center;font-weight:bold;color:${precColor}">${precSymbol} ${_precL(ec.precision)}</td>
                </tr>`;
                const _ecD = _descL(ec);
                if (_ecD) {
                    s += `<tr style="background:#fffbeb"><td colspan="5" style="font-style:italic;color:#5d4037;font-size:0.88em;padding:6px 12px 10px">${escH(_ecD)}</td></tr>`;
                }
