// Intensité de base par aspect (avant pondération orbe et planète).
const ASPECT_INTENSITY_BASE = {
    "Conjonction": 9,
    "Opposition": 8,
    "Carré": 7,
    "Trigone": 6,
    "Sextile": 4,
