    };
    const m7a = getHouse7Ruler(housesA);
    const m7b = getHouse7Ruler(housesB);
    const result = { ruler_a: m7a.ruler, sign_a: m7a.sign, ruler_b: m7b.ruler, sign_b: m7b.sign, cross_aspects: [] };

    if (m7a.ruler && m7b.ruler) {
