    const _p2 = (globalScoreDetail && (globalScoreDetail.pilier2_karmique || globalScoreDetail.pilier2)) || {};
    const _li = longevityIndex || {};
    const _bd = _li.breakdown || {};

    // Harmonie moyenne d'une maison (moyenne des 2 directions), neutre = 50
    const houseHarmony = (h) => {
        const a = houseHIBinA[h] || houseHIBinA[String(h)] || {};
        const b = houseHIAinB[h] || houseHIAinB[String(h)] || {};
        const vals = [a.harmony, b.harmony].filter((v) => typeof v === "number");
