    // Relation de signe fondamentale pour une planète personnelle
    const signRel = (planet) => {
        const pairs = (_p4.sign_compatibility && _p4.sign_compatibility.pairs) || [];
        const p = pairs.find((x) => x.planet === planet);
        if (!p) return 0;
        return p.relation === "same_element" ? 15
            : p.relation === "compatible" ? 8
            : p.relation === "incompatible" ? -10
            : p.relation === "aversion" ? -15 : 0;
    };
