    const hasBonus = (id) => ((_p4.bonuses || []).some((b) => b.id === id));
    const hasPen = (id) => ((_p4.penalties || []).some((p) => p.id === id));
    const homo = (soft, hard) => (hasBonus(soft) ? 25 : 0) - (hasPen(hard) ? 25 : 0);

    // Bandes qualitatives (couleurs douces, sans connotation d'échec)
    const bandQuality = (s, isEN) => s >= 75 ? { fr: "Très fort", en: "Very strong", c: "#16a34a" }
        : s >= 60 ? { fr: "Fort", en: "Strong", c: "#2563eb" }
