    const bandIntensity = (s) => s >= 75 ? { fr: "Très intense", en: "Very intense", c: "#7c3aed" }
        : s >= 60 ? { fr: "Intense", en: "Intense", c: "#8b5cf6" }
        : s >= 45 ? { fr: "Modérée", en: "Moderate", c: "#a78bfa" }
        : s >= 30 ? { fr: "Légère", en: "Light", c: "#c4b5fd" }
