    const bandKarmic = (s) => s >= 75 ? { fr: "Très marqué", en: "Very marked", c: "#9333ea" }
        : s >= 60 ? { fr: "Marqué", en: "Marked", c: "#a855f7" }
        : s >= 45 ? { fr: "Présent", en: "Present", c: "#c084fc" }
        : s >= 30 ? { fr: "Léger", en: "Light", c: "#d8b4fe" }
        : { fr: "Discret", en: "Faint", c: "#cbd5e1" };

    const mk = (score, band, desc, desc_en, extra) => Object.assign({
        score: clamp(score),
        label: band.fr, label_en: band.en, color: band.c,
        desc, desc_en
    }, extra || {});

    // 1. Fluidité (= harmony V6)
    const fluiditeScore = clamp(globalScoreDetail.harmony);
    // 2. Intensité (= intensity V6)
    const intensiteScore = clamp(globalScoreDetail.intensity);
    // 3. Durabilité (= longevityIndex /15)
    const durabiliteScore = clamp((Number(_li.score) || 0) / 15 * 100);
    // 4. Karmique (quantité de contact nodal + direction)
    const nq = Number(_p2.nodal_qual_score) || 0;            // qualité nodale pondérée (~0..12, pas un compte)
