    const valeursScore = clamp(0.5 * houseHarmony(2) + 0.5 * valeursAspect);
    // 8. Résonance publique (Maisons X + XI)
    const resonanceScore = clamp((houseHarmony(10) + houseHarmony(11)) / 2);

