// v7.6.0 — Synthèse Relationnelle découpée en chapitres : une bannière marine + une carte
// blanche par section « ## » du texte LLM. Rendu structuré « pro » harmonisé avec THEME et
// pagination saine (chaque chapitre est un bloc autonome, plus de mur de 4 pages d'un bloc).
// Découpage partagé du texte LLM en chapitres (« ## titre ## »), utilisé à la fois
// par le rendu des sections et par le sommaire (pour que les deux restent alignés).
function _parseSyntheseBlocks() {
    if (!synthese) return [];
    // NOUVEAU FORMAT (Reassemble Trad SYN v4) : chapitres re-tissés structurés.
    // Le titre vient des métadonnées ; le corps contient des sous-titres « ## »
    // (punchlines) + un « ## En pratique » -> rendu via mdRecit().
    if (Array.isArray(synthese.chapters) && synthese.chapters.length) {
        return synthese.chapters
            .filter((c) => c && (String(c.title || '').trim() || String(c.body || '').trim()))
            .map((c) => ({
                title: String(c.title || '').replace(/\*/g, '').replace(/^\d+\.\s*/, '').trim(),
                // _cleanSynRaw : retire notamment toute ligne « Note globale d'harmonie »
                // émise par le LLM (rendue désormais en bloc verdict déterministe).
                body: _cleanSynRaw(String(c.body || '')).split('\n'),
                _recit: true,
            }));
    }
    if (!String(synthese.llm_text || '').trim()) return [];
    const raw = _cleanSynRaw(String(synthese.llm_text));
    const lines = raw.split('\n');
    const blocks = [];
    let cur = null;
    for (const ln of lines) {
        const hm = ln.match(/^#{1,3}\s+(.+?)\s*#*\s*$/);
        if (hm && !/^#{1,3}\s*$/.test(ln)) {
            if (cur) blocks.push(cur);
            cur = { title: hm[1].replace(/\*/g, '').replace(/^\d+\.\s*/, '').trim(), body: [] };
        } else {
            if (!cur) cur = { title: '', body: [] };
            cur.body.push(ln);
        }
    }
    if (cur) blocks.push(cur);
    return blocks.filter((b) => b.title || String(b.body.join('')).trim());
}

// Descriptif (sous-titre) par chapitre de synthèse — calé sur les 7 chapitres
// canoniques imposés au LLM. Match par mots-clés (robuste aux variations de titre),
// pour reproduire le gabarit THEME final (numéro + titre + descriptif).
function _synChapSub(rawTitle) {
    const t = String(rawTitle || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const rules = [
        { k: ['rencontre', 'encounter', 'how you met', 'meeting'], fr: `Ce qui s'est joué quand les ciels de ${persoA} et ${persoB} se sont rencontrés`, en: `What unfolded when ${persoA}'s and ${persoB}'s skies met` },
        { k: ['attraction', 'alchimie', 'alchemy', 'chemistry'], fr: `Le magnétisme, le désir et la chimie entre ${persoA} et ${persoB}`, en: `The magnetism, desire and chemistry between ${persoA} and ${persoB}` },
        { k: ['intimite', 'intimacy', 'dialogue', 'emotion'], fr: "La communication, la compréhension mutuelle et le partage des émotions", en: "Communication, mutual understanding and the sharing of emotions" },
        { k: ['defi', 'challenge'], fr: "Les zones de friction et les tensions à apprivoiser ensemble", en: "The friction zones and tensions to tame together" },
        { k: ['engagement', 'avenir', 'commitment', 'future'], fr: "L'engagement mutuel, la durée et les projets tournés vers demain", en: "Mutual commitment, endurance and future-facing plans" },
        { k: ['nous', 'the we', 'we you create', 'we\u201d'], fr: "L'identité commune et la dynamique unique du lien", en: "The shared identity and unique dynamic of the bond" },
        { k: ['resume', 'conseil', 'summary', 'advice', 'takeaway'], fr: "L'essentiel à retenir et des repères concrets pour avancer", en: "The key takeaways and concrete pointers to move forward" },
    ];
    for (const r of rules) { if (r.k.some((x) => t.includes(x))) return isEN ? r.en : r.fr; }
    return '';
}

// Verdict d'harmonie DÉTERMINISTE — construit depuis les données moteur (jamais le LLM).
// Phrase : « Note globale d'harmonie : XX/100 — <bande qualitative>. »
//  - score = indice Harmonie du tableau de bord (= global_score_detail.harmony)
//  - bande = global_score_detail.qualitative_band (texte affiché aussi en haut du tableau de bord)
// Rendu UNIQUEMENT si les deux sont présents (sinon rien : pas de phrase bancale "pour tous les cas").
function _harmonyVerdict() {
    if (!(globalScore > 0)) return '';
    const dash = synData.relationship_dashboard || (prepData._synRef || {}).relationship_dashboard || null;
    const qb = globalScoreDetail?.qualitative_band || {};
    let h = dash?.metrics?.fluidite?.score;
    if (h == null) h = globalScoreDetail?.harmony;
    const band = isEN ? (qb.band_en || qb.band) : (qb.band || qb.band_en);
    if (h == null || !band) return '';
    const score = Math.max(0, Math.min(100, Math.round(h)));
    const label = isEN ? 'Overall harmony score' : "Note globale d'harmonie";
    // Police ALIGNÉE sur le mantra de clôture du THEME final (.sk-traj-mantra-box / .sk-traj-mantra) :
    // corps italique 600, 19px, couleur primaire, centré, boîte rose arrondie.
    return '<div class="syn-verdict" style="background:rgba(255,166,246,0.20);border:1.5px solid rgba(255,166,246,0.6);border-radius:20px;padding:1.5rem 2.2rem;margin:1rem 0 1.8rem;text-align:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;page-break-inside:avoid;">'
        + '<div style="font-size:11px;letter-spacing:2.5px;text-transform:uppercase;color:var(--ink-soft);font-weight:700;margin-bottom:9px">' + label + '</div>'
        + '<p style="font-family:var(--font-body);font-weight:600;font-size:19px;line-height:1.6;color:var(--primary);font-style:italic;text-align:center;max-width:84%;margin:0 auto;">'
        + '<strong style="font-weight:800;font-style:normal">' + score + '/100</strong> — ' + esc(band)
        + '</p></div>';
}

