const _EMPR_SIGN_ELEM = { "Bélier":"Feu","Lion":"Feu","Sagittaire":"Feu","Taureau":"Terre","Vierge":"Terre","Capricorne":"Terre","Gémeaux":"Air","Balance":"Air","Verseau":"Air","Cancer":"Eau","Scorpion":"Eau","Poissons":"Eau" };
const _EMPR_ELEMENTS = isEN ? { Feu:"Fire", Terre:"Earth", Air:"Air", Eau:"Water" } : { Feu:"Feu", Terre:"Terre", Air:"Air", Eau:"Eau" };
