const _isRencontreChap = (t) => { const s = String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); return ['rencontre', 'encounter', 'how you met', 'meeting'].some(k => s.includes(k)); };

function buildSyntheseSections() {
    const blocks = _parseSyntheseBlocks();
    if (!blocks.length) return '';
    // Tableau "Empreinte" inséré juste après la bannière du chapitre "rencontre"
    // (1er chapitre relationnel par défaut) : repli sur l'index 0 si non détecté.
    const empreinteHtml = buildEmpreinteSYN();
    let _emprIdx = blocks.findIndex(b => _isRencontreChap(b.title));
    if (_emprIdx < 0) _emprIdx = 0;
    let out = '', shown = 0;
    blocks.forEach((b, i) => {
        const isRecit = !!b._recit;
        const isLast = i === blocks.length - 1;
        const bodyHtml = (isRecit ? mdRecit : md)(b.body.join('\n'))
            .replace(/^(<div style="height:[\d]+px;"><\/div>)+/, '');
        const title = b.title || (isEN ? 'Relationship Synthesis' : 'Synthèse Relationnelle');
        // Le verdict d'harmonie déterministe ouvre le DERNIER chapitre (clôture/résumé).
        const verdict = isLast ? _harmonyVerdict() : '';
        const empreinteHere = (i === _emprIdx) ? empreinteHtml : '';
        // Chapitre porteur des tableaux Empreinte : démarrage sur page fraîche pour
        // que bannière + 2 tableaux tiennent ensemble (évite coupure/orphelin Chromium).
        const chapStyle = (i === _emprIdx && empreinteHtml) ? ' style="page-break-before:always;break-before:page;"' : '';
        out += `<div id="syn-chap-${i}"${chapStyle}>${skSection(_synFinalNo['syn-chap-' + i] || '', title, _synChapSub(title))}${empreinteHere}</div>`;
        // En mode récit, les punchlines sont déjà des cartes : pas d'enveloppe sk-card
        // (sinon carte dans la carte). En legacy on conserve l'enveloppe sk-card.
        // Chapitre Empreinte : le corps du texte démarre sur une page propre (les 2
        // tableaux occupent la page précédente, pas de 3 lignes orphelines en bas).
        const bodyStyle = (i === _emprIdx && empreinteHtml) ? ' style="page-break-before:always;break-before:page;"' : '';
        out += isRecit
            ? `<div class="synthese-section"${bodyStyle}>${verdict}${bodyHtml}</div>`
            : `<div class="synthese-section sk-card"${bodyStyle}>${verdict}${bodyHtml}</div>`;
        shown++;
    });
    return shown ? `<div id="syn-final-synthese">${out}</div>` : '';
}

