    // Couronne des signes : wash élément discret (cohérent avec la roue du THEME)
    for (let i = 0; i < 12; i++) {
        const a1 = e2s(i*30), a2 = e2s((i+1)*30);
        const o1 = pol(a1,R_SO), o2 = pol(a2,R_SO), i1 = pol(a1,R_SI), i2 = pol(a2,R_SI);
        const col = signElem(i);
        svg.push(`<path d="M${i1.x.toFixed(2)},${i1.y.toFixed(2)} L${o1.x.toFixed(2)},${o1.y.toFixed(2)} A${R_SO},${R_SO} 0 0,0 ${o2.x.toFixed(2)},${o2.y.toFixed(2)} L${i2.x.toFixed(2)},${i2.y.toFixed(2)} A${R_SI},${R_SI} 0 0,1 ${i1.x.toFixed(2)},${i1.y.toFixed(2)} Z" fill="${col}" fill-opacity="0.13" stroke="none"/>`);
        const sb = e2s(i*30), b1 = pol(sb,R_SI), b2 = pol(sb,R_SO);
        svg.push(`<line x1="${b1.x.toFixed(2)}" y1="${b1.y.toFixed(2)}" x2="${b2.x.toFixed(2)}" y2="${b2.y.toFixed(2)}" stroke="${NAVY2}" stroke-width="1" opacity="0.55"/>`);
        const gp = pol(e2s(i*30+15), R_SG);
        svg.push(`<text x="${gp.x.toFixed(2)}" y="${gp.y.toFixed(2)}" font-size="22" text-anchor="middle" dominant-baseline="central" fill="${col}" font-family="${GLYPH_FONT}" font-weight="bold">${signGlyphs[i]}</text>`);
    }

    // Graduations 5° / 10° vers l'EXTÉRIEUR (dans la bande du signe)
    for (let deg = 0; deg < 360; deg++) {
        if (deg % 5 !== 0 || deg % 30 === 0) continue;
        const isTen = (deg % 10 === 0);
        const len = isTen ? 12 : 7;
        const ta = e2s(deg), t1 = pol(ta, R_SI), t2 = pol(ta, R_SI + len);
        svg.push(`<line x1="${t1.x.toFixed(2)}" y1="${t1.y.toFixed(2)}" x2="${t2.x.toFixed(2)}" y2="${t2.y.toFixed(2)}" stroke="${isTen ? NAVY2 : "#8c99b8"}" stroke-width="${isTen ? 1.4 : 0.9}" opacity="${isTen ? 0.9 : 0.7}"/>`);
    }

    svg.push(`<circle cx="${CX}" cy="${CY}" r="${R_SI}" fill="none" stroke="${NAVY2}" stroke-width="1.4"/>`);
    svg.push(`<circle cx="${CX}" cy="${CY}" r="${(R_PA + R_PB) / 2}" fill="none" stroke="#d0d6e4" stroke-width="0.7" stroke-dasharray="3,4"/>`);
    svg.push(`<circle cx="${CX}" cy="${CY}" r="${R_HI}" fill="url(#hgSyn)" stroke="#b9c2d6" stroke-width="1"/>`);

    const axMap = {0:"AC",3:"IC",6:"DC",9:"MC"};
    if (bwCuspsA.length >= 12) {
        for (let i = 0; i < 12; i++) {
            const cEcl = bwCuspsA[i].degree, svgAng = e2s(cEcl);
            const isAxis = [0,3,6,9].includes(i);
            const pOut = pol(svgAng,R_SI), pIn = pol(svgAng,R_HI);
            svg.push(`<line x1="${pOut.x.toFixed(2)}" y1="${pOut.y.toFixed(2)}" x2="${pIn.x.toFixed(2)}" y2="${pIn.y.toFixed(2)}" stroke="${isAxis ? NAVY : "#c2cbe0"}" stroke-width="${isAxis ? 2.6 : 0.8}" ${isAxis ? "" : 'stroke-dasharray="4,4"'}/>`);
            const nxEcl = bwCuspsA[(i+1)%12].degree, span = (nxEcl - cEcl + 360)%360;
            const midEcl = (cEcl + span/2 + 360)%360, nPos = pol(e2s(midEcl), R_HN);
            svg.push(`<text x="${nPos.x.toFixed(2)}" y="${nPos.y.toFixed(2)}" font-size="20" text-anchor="middle" dominant-baseline="central" fill="#9aa6c0" font-weight="700" font-family="'Source Sans 3',Arial,sans-serif">${i+1}</text>`);
            if (isAxis) {
                const axPos = pol(svgAng, R_OUT + 24);
                const _ad = ((cEcl % 360) + 360) % 360, _adeg = _ad % 30;
                const _add = Math.floor(_adeg); let _amm = Math.round((_adeg - _add) * 60), _addl = _add; if (_amm === 60) { _amm = 0; _addl += 1; }
                svg.push(`<text x="${axPos.x.toFixed(2)}" y="${(axPos.y - 8).toFixed(2)}" font-size="16" text-anchor="middle" dominant-baseline="central" fill="${NAVY}" font-weight="900" font-family="'Source Sans 3',Arial,sans-serif">${axMap[i]}</text>`);
                svg.push(`<text x="${axPos.x.toFixed(2)}" y="${(axPos.y + 8).toFixed(2)}" font-size="9.5" text-anchor="middle" dominant-baseline="central" fill="${NAVY2}" font-weight="700" font-family="'Source Sans 3',Arial,sans-serif">${_addl}°${String(_amm).padStart(2,"0")}'</text>`);
            }
        }
    }

    const aspDef = { "Conjonction":{col:"#9900dd",w:2.0,op:0.85,z:5}, "Opposition":{col:"#cc0000",w:1.8,op:0.8,z:4}, "Carré":{col:"#ee4400",w:1.5,op:0.75,z:3}, "Trigone":{col:"#1155cc",w:1.2,op:0.65,z:2}, "Sextile":{col:"#009944",w:0.9,op:0.55,z:1} };
    // Trame d'aspects = corps « aspectants » classiques uniquement (planètes + luminaires + Chiron),
    // côté A ET côté B → centre lisible (mêmes critères que la roue du THEME).
    const ASPECT_BODIES = new Set(["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron"]);
    const posMapA = {}, posMapB = {};
    bwPlanetsA.forEach(p => { if (p.name) posMapA[p.name] = p.fullDeg; });
    bwPlanetsB.forEach(p => { if (p.name) posMapB[p.name] = p.fullDeg; });
    const bwAspects = [...interAspectsTier1BtoA, ...interAspectsTier1AtoB]
        .filter(a => aspDef[a.aspect] && ASPECT_BODIES.has(a.planete_source) && ASPECT_BODIES.has(a.planete_cible));
    bwAspects.sort((a,b) => (aspDef[a.aspect]?.z||0)-(aspDef[b.aspect]?.z||0));
    bwAspects.forEach(asp => {
        const st = aspDef[asp.aspect];
        const degSrc = posMapA[asp.planete_source] ?? posMapB[asp.planete_source];
        const degTgt = posMapA[asp.planete_cible] ?? posMapB[asp.planete_cible];
        if (degSrc == null || degTgt == null) return;
        const a1 = d2r(e2s(degSrc)), a2 = d2r(e2s(degTgt));
        svg.push(`<line x1="${(CX+R_AS*Math.cos(a1)).toFixed(1)}" y1="${(CY+R_AS*Math.sin(a1)).toFixed(1)}" x2="${(CX+R_AS*Math.cos(a2)).toFixed(1)}" y2="${(CY+R_AS*Math.sin(a2)).toFixed(1)}" stroke="${st.col}" stroke-width="${st.w}" opacity="${st.op}"/>`);
    });

    const skipPl = ["Descendant","Imum Coeli","Ascendant","Milieu du Ciel"];
    const isLotName = nm => /^Lot /.test(nm);   // lots hermétiques exclus de la bi-roue (décision design)

    // Éventail angulaire à ORDRE ZODIACAL GARANTI (identique à la roue du THEME).
    const fanPlace = (arr, baseR, minGap) => {
        arr.forEach(p => { p.trueA = norm360(p.fullDeg); p.displayA = p.trueA; p.radius = baseR; });
        const n = arr.length; if (n === 0) return;
        arr.sort((a, b) => a.trueA - b.trueA);
        if (n === 1 || n * minGap >= 350) return;
        let cut = 0, maxGap = -1;
        for (let i = 0; i < n; i++) { const g = norm360(arr[(i + 1) % n].trueA - arr[i].trueA); if (g > maxGap) { maxGap = g; cut = (i + 1) % n; } }
        const order = []; for (let k = 0; k < n; k++) order.push(arr[(cut + k) % n]);
        const lin = [0]; for (let k = 1; k < n; k++) lin[k] = lin[k - 1] + norm360(order[k].trueA - order[k - 1].trueA);
        const orig = lin.slice();
        for (let k = 1; k < n; k++) if (lin[k] < lin[k - 1] + minGap) lin[k] = lin[k - 1] + minGap;
        let shift = 0; for (let k = 0; k < n; k++) shift += lin[k] - orig[k]; shift /= n;
        const span = lin[n - 1] - lin[0]; if (360 - span >= minGap) for (let k = 0; k < n; k++) lin[k] -= shift;
        const base = order[0].trueA; order.forEach((p, k) => { p.displayA = norm360(base + lin[k]); });
    };

    let svgLines = "", svgGlyphs = "";
    // Tick au degré réel + rappel UNIQUEMENT si le glyphe est décalé (façon Luna / THEME).
    const drawPointer = (p, glyphR, col, lw) => {
        const trueS = e2s(p.trueA);
        const t1 = pol(trueS, R_SI), t2 = pol(trueS, R_SI - 7);
        svgLines += `<line x1="${t1.x.toFixed(1)}" y1="${t1.y.toFixed(1)}" x2="${t2.x.toFixed(1)}" y2="${t2.y.toFixed(1)}" stroke="${col}" stroke-width="${lw}" opacity="0.8"/>`;
        const off = Math.abs(angDiff(p.displayA, p.trueA));
        if (off > 1.5) {
            const g = pol(e2s(p.displayA), glyphR);
            svgLines += `<line x1="${t2.x.toFixed(1)}" y1="${t2.y.toFixed(1)}" x2="${g.x.toFixed(1)}" y2="${g.y.toFixed(1)}" stroke="${col}" stroke-width="0.8" opacity="0.6"/>`;
        }
    };

    const buildRing = (planets, baseR, color) => {
        const arr = planets
            .filter(p => p.name && !skipPl.includes(p.name) && !isLotName(p.name))
            .map(p => ({ name: p.name, fullDeg: p.fullDeg, norm: ((p.fullDeg % 30) + 30) % 30, retro: !!p.retro }));
        fanPlace(arr, baseR, 6.5);
        arr.forEach(p => {
            const svgA = e2s(p.displayA), pos = pol(svgA, p.radius);
            const glyph = pGlyphs[p.name] || "?";
            drawPointer(p, p.radius + R_GLYPH, color, 1.0);
            const isMV = (glyph === "♀" || glyph === "♂");
            // ♀/♂ ont un œil plus petit dans Noto Sans Symbols 2 → on remonte leur corps pour égaliser la taille visuelle.
            const fsz = isMV ? 21 : 18;
            const extra = isMV ? `stroke-width="2.6"` : `stroke-width="2.3"`;
            svgGlyphs += `<text x="${pos.x.toFixed(1)}" y="${pos.y.toFixed(1)}" font-size="${fsz}" text-anchor="middle" dominant-baseline="central" fill="${color}" stroke="#ffffff" ${extra} paint-order="stroke" font-weight="bold" font-family="${GLYPH_FONT}">${glyph}</text>`;
            const _dd = Math.floor(p.norm); let _mm = Math.round((p.norm - _dd) * 60), _ddl = _dd; if (_mm === 60) { _mm = 0; _ddl = _dd + 1; }
            const degTxt = `${_ddl}°${String(_mm).padStart(2, "0")}'${p.retro ? " ℞" : ""}`;
            const lbl = pol(svgA, p.radius - R_GLYPH - 6);
            svgGlyphs += `<text x="${lbl.x.toFixed(1)}" y="${lbl.y.toFixed(1)}" font-size="7.5" text-anchor="middle" dominant-baseline="central" fill="${p.retro ? "#b23030" : color}" stroke="#ffffff" stroke-width="2.0" paint-order="stroke" font-weight="700" font-family="'Source Sans 3','Segoe UI Symbol','Noto Sans Symbols 2',sans-serif" letter-spacing="-0.3">${degTxt}</text>`;
        });
    };
    buildRing(bwPlanetsA, R_PA, COLOR_A);
    buildRing(bwPlanetsB, R_PB, COLOR_B);
    svg.push(svgLines);
    svg.push(svgGlyphs);

    // ── Étoiles fixes : un label PAR ÉTOILE (dédupliqué par personne), color-codées A/B, anti-chevauchement ──
    const ANGLE_HOSTS = ["Ascendant","Descendant","Milieu du Ciel","Imum Coeli"];
    // Longitudes écliptiques J2000 du catalogue (nœud « 3c. Étoiles Fixes ») : on ancre chaque étiquette
    // sur le degré RÉEL de l'étoile (ordre relatif stable à la précession) → ordre zodiacal garanti.
    const STAR_LON = {"Algol":56.22,"Pléiades":59.98,"Pleiades":59.98,"Aldébaran":69.78,"Aldebaran":69.78,"Sirius":104.05,"Régulus":149.83,"Regulus":149.83,"Spica":203.836,"Antarès":249.77,"Antares":249.77,"Véga":285.32,"Vega":285.32,"Fomalhaut":333.87,"Rigel":76.83,"Bételgeuse":88.75,"Betelgeuse":88.75,"Canopus":104.97,"Castor":110.25,"Pollux":113.22,"Procyon":115.78,"Arcturus":204.23,"Vindemiatrix":189.95,"Zubenelgenubi":225.08,"Zubeneschamali":229.37,"Deneb Algedi":323.55,"Scheat":359.37,"Achernar":345.32,"Deneb":335.33,"Mirach":30.43,"Mirfak":62.06,"Bellatrix":80.94,"Capella":81.95,"Alphecca":222.3,"Toliman":239.85,"Lesath":264.22,"Polis":273.23,"Facies":278.3,"Ascella":283.67,"Altaïr":301.66,"Altair":301.66,"Sadalmelik":333.48,"Markab":353.486,"Praesepe":127.282,"Asellus Borealis":127.538,"Asellus Australis":128.722};
    const starAcc = {};   // clé = couleur|nom (dédup par personne) -> conjonction la plus serrée
    const collectStars = (matches, posMap, color) => {
        (matches || []).forEach(em => {
            if (posMap[em.planete] === undefined) return;
            const name = isEN ? (em.etoile_en || em.etoile) : em.etoile;
            const lon = (typeof STAR_LON[name] === "number") ? STAR_LON[name]
                      : (typeof STAR_LON[em.etoile] === "number") ? STAR_LON[em.etoile]
                      : posMap[em.planete];
            const orb = (typeof em.orb === "number") ? em.orb : (parseFloat(em.orb) || 99);
            const isAngleHost = ANGLE_HOSTS.includes(em.planete);
            const key = color + "|" + name;
            const prev = starAcc[key];
            if (!prev || orb < prev.orb) starAcc[key] = { name, color, lon, orb, isAngleHost: isAngleHost || (prev && prev.isAngleHost) };
            else if (isAngleHost) prev.isAngleHost = true;
        });
    };
    collectStars(input.etoile_matches_a, posMapA, COLOR_A);
    collectStars(input.etoile_matches_b, posMapB, COLOR_B);
    // tri ZODIACAL (par longitude réelle) puis anti-chevauchement qui étale chaque grappe (A + B confondus) SANS permuter
    let starLabels = Object.values(starAcc).map(v => ({ name: v.name, color: v.color, norm: ((e2s(v.lon) % 360) + 360) % 360, isAngleHost: v.isAngleHost }));
    const STAR_GAP = 2.4;
    starLabels.sort((a, b) => a.norm - b.norm);
    if (starLabels.length > 1) {
        const clusters = []; let cur = [starLabels[0]];
        for (let i = 1; i < starLabels.length; i++) {
            if (starLabels[i].norm - starLabels[i - 1].norm < STAR_GAP) cur.push(starLabels[i]);
            else { clusters.push(cur); cur = [starLabels[i]]; }
        }
        clusters.push(cur);
        if (clusters.length > 1) {
            const first = clusters[0], last = clusters[clusters.length - 1];
            if ((first[0].norm + 360) - last[last.length - 1].norm < STAR_GAP) { clusters[0] = last.concat(first); clusters.pop(); }
        }
        for (const cl of clusters) {
            if (cl.length < 2) continue;
            const mean = cl.reduce((acc, L) => acc + L.norm, 0) / cl.length;
            const span = (cl.length - 1) * STAR_GAP;
            cl.forEach((L, k) => { L.norm = (((mean - span / 2 + k * STAR_GAP) % 360) + 360) % 360; });
        }
    }
    starLabels.forEach(L => {
        const svgA = L.norm;
        const flip = (svgA > 90 && svgA < 270);
        const rot = flip ? svgA + 180 : svgA;
        const anchor = flip ? "end" : "start";
        const base = L.isAngleHost ? R_OUT + 50 : R_OUT + 11;
        const a0 = pol(svgA, R_OUT + 1), a1 = pol(svgA, base - 2);
        svg.push(`<line x1="${a0.x.toFixed(1)}" y1="${a0.y.toFixed(1)}" x2="${a1.x.toFixed(1)}" y2="${a1.y.toFixed(1)}" stroke="${L.color}" stroke-width="0.6" opacity="0.55"/>`);
        const tp = pol(svgA, base);
        svg.push(`<text x="${tp.x.toFixed(1)}" y="${tp.y.toFixed(1)}" transform="rotate(${rot.toFixed(1)} ${tp.x.toFixed(1)} ${tp.y.toFixed(1)})" text-anchor="${anchor}" dominant-baseline="central" font-size="8.5" fill="${L.color}" font-style="italic" font-weight="600" font-family="'Source Sans 3',Arial,sans-serif">${L.name}</text>`);
    });

    svg.push(`<circle cx="${CX}" cy="${CY}" r="7" fill="#2E1560" stroke="white" stroke-width="2"/>`);
    svg.push(`<circle cx="${CX}" cy="${CY}" r="2.5" fill="white"/>`);

    const biWheelSVG = `<svg viewBox="-90 -90 980 980" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:880px;height:auto;display:block;margin:auto;">${svg.join('')}</svg>`;

    _wheelSVG = biWheelSVG;
    _personLegend = `<div style="display:flex;justify-content:center;gap:30px;margin:0 0 10px;flex-wrap:wrap;">
        <span style="display:flex;align-items:center;gap:6px"><span style="display:inline-block;width:16px;height:16px;border-radius:50%;background:${COLOR_A};border:2px solid ${COLOR_A}"></span><strong style="color:${COLOR_A}">${prenomA} ${nomA}</strong> (${isEN?'outer ring':'anneau ext.'})</span>
        <span style="display:flex;align-items:center;gap:6px"><span style="display:inline-block;width:16px;height:16px;border-radius:50%;background:${COLOR_B};border:2px solid ${COLOR_B}"></span><strong style="color:${COLOR_B}">${prenomB} ${nomB}</strong> (${isEN?'inner ring':'anneau int.'})</span>
    </div>`;
    _colorLegend = `<div style="display:flex;flex-wrap:wrap;justify-content:center;gap:14px;align-items:center;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:8px 12px;margin:0 0 12px;font-size:13px;">
        <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#9900dd" stroke-width="3"/></svg><span style="color:#9900dd;font-weight:bold">${isEN ? 'Conjunction' : 'Conjonction'}</span></span>
        <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#cc0000" stroke-width="2.5"/></svg><span style="color:#cc0000;font-weight:bold">Opposition</span></span>
        <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#ee4400" stroke-width="2"/></svg><span style="color:#ee4400;font-weight:bold">${isEN ? 'Square' : 'Carré'}</span></span>
        <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#1155cc" stroke-width="1.7"/></svg><span style="color:#1155cc;font-weight:bold">${isEN ? 'Trine' : 'Trigone'}</span></span>
        <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#009944" stroke-width="1.3"/></svg><span style="color:#009944;font-weight:bold">Sextile</span></span>
    </div>`;
    const _legHdr = (t) => `<div style="background:#1F3864;color:#fff;font-family:'Playfair Display',Georgia,serif;font-size:15px;font-weight:600;padding:0 14px;border-radius:8px;height:42px;display:flex;align-items:center;justify-content:center;text-align:center;margin:0 0 12px;-webkit-print-color-adjust:exact;print-color-adjust:exact;">${t}</div>`;
    const _legRow = (g, lbl, col, bold) => `<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;white-space:nowrap;"><span style="font-size:1.4em;width:25px;text-align:center;font-weight:${bold?900:'bold'};font-family:${GLYPH_FONT};color:${col||'#1F3864'};${bold?'-webkit-text-stroke:1px #1F3864;':''}">${g}</span> ${lbl}</div>`;
    _symbolsLegend = `<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:15px;margin-top:18px;text-align:left;font-size:1.0em;border-top:1px solid #eee;padding-top:18px;break-inside:avoid;page-break-inside:avoid;">
        <div>${_legHdr(isEN ? 'Planets and Objects' : 'Planètes et Objets')}
            ${_legRow('☉', isEN?'Sun':'Soleil')}${_legRow('☽', isEN?'Moon':'Lune')}${_legRow('☿', isEN?'Mercury':'Mercure')}${_legRow('♀', isEN?'Venus':'Vénus', '#1F3864', true)}${_legRow('♂', 'Mars', '#1F3864', true)}${_legRow('♃', 'Jupiter')}${_legRow('♄', isEN?'Saturn':'Saturne')}${_legRow('♅', 'Uranus')}${_legRow('♆', 'Neptune')}${_legRow('♇', isEN?'Pluto':'Pluton')}${_legRow('⚷', 'Chiron')}${_legRow('☊', isEN?'North Node':'Nœud Nord')}${_legRow('☋', isEN?'South Node':'Nœud Sud')}${_legRow('⚸', 'Lilith')}${_legRow('⊕', isEN?'Part of Fortune':'Part de Fortune')}
        </div>
        <div>${_legHdr(isEN ? 'Zodiac Signs' : 'Signes du Zodiaque')}
            ${_legRow('♈', (isEN?'Aries':'Bélier')+' — <small>'+(isEN?'Fire / Cardinal':'Feu / Cardinal')+'</small>', '#1F3864')}${_legRow('♉', (isEN?'Taurus':'Taureau')+' — <small>'+(isEN?'Earth / Fixed':'Terre / Fixe')+'</small>', '#2E5FA3')}${_legRow('♊', (isEN?'Gemini':'Gémeaux')+' — <small>'+(isEN?'Air / Mutable':'Air / Mutable')+'</small>', '#1F3864')}${_legRow('♋', 'Cancer — <small>'+(isEN?'Water / Cardinal':'Eau / Cardinal')+'</small>', '#2E5FA3')}${_legRow('♌', (isEN?'Leo':'Lion')+' — <small>'+(isEN?'Fire / Fixed':'Feu / Fixe')+'</small>', '#1F3864')}${_legRow('♍', (isEN?'Virgo':'Vierge')+' — <small>'+(isEN?'Earth / Mutable':'Terre / Mutable')+'</small>', '#2E5FA3')}${_legRow('♎', (isEN?'Libra':'Balance')+' — <small>'+(isEN?'Air / Cardinal':'Air / Cardinal')+'</small>', '#1F3864')}${_legRow('♏', (isEN?'Scorpio':'Scorpion')+' — <small>'+(isEN?'Water / Fixed':'Eau / Fixe')+'</small>', '#2E5FA3')}${_legRow('♐', (isEN?'Sagittarius':'Sagittaire')+' — <small>'+(isEN?'Fire / Mutable':'Feu / Mutable')+'</small>', '#1F3864')}${_legRow('♑', (isEN?'Capricorn':'Capricorne')+' — <small>'+(isEN?'Earth / Cardinal':'Terre / Cardinal')+'</small>', '#2E5FA3')}${_legRow('♒', (isEN?'Aquarius':'Verseau')+' — <small>'+(isEN?'Air / Fixed':'Air / Fixe')+'</small>', '#1F3864')}${_legRow('♓', (isEN?'Pisces':'Poissons')+' — <small>'+(isEN?'Water / Mutable':'Eau / Mutable')+'</small>', '#2E5FA3')}
        </div>
