            </div>
        </div>
    </div>`;
    html = `<div style="text-align:center;margin:10px 0">${_personLegend}${biWheelSVG}</div>`;
}
    return { svg: html, present: !!_wheelSVG, wheel: _wheelSVG, personLegend: _personLegend, colorLegend: _colorLegend, symbolsLegend: _symbolsLegend };
}

