function _synSubDirection(label, color, soft, dark, llm_text, hi, overlayCount, cuspCount) {
  const isEmpty = _isReallyEmpty(hi, overlayCount, cuspCount);
  const ton = synTonalite(hi ? Math.round(hi.harmony) : null, isEmpty);
  const tip = hi ? (isEN ? `Harmony ${Math.round(hi.harmony)}/100 · intensity ${Math.round(hi.intensity)}/100` : `Harmonie ${Math.round(hi.harmony)}/100 · intensité ${Math.round(hi.intensity)}/100`) : '';
  return `<div style="margin:14px 0 0;">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;background:${soft};border-left:4px solid ${color};padding:8px 14px;border-radius:0 8px 8px 0;">
      <span style="font-size:14px;font-weight:700;color:${dark};">${label}</span>
      <span title="${tip}" style="display:inline-block;background:${ton.bg};color:${ton.txt};font-size:12.5px;font-weight:700;padding:3px 11px;border-radius:20px;white-space:nowrap;">${ton.lab}</span>
    </div>
    <div style="padding:12px 22px 2px;">${md(llm_text)}</div>
  </div>`;
}

