  const oC_A = (overlayBinA[String(h)] || []).length, oC_B = (overlayAinB[String(h)] || []).length;
  const cC_A = _cuspBinA.filter(c => c.maison_cuspide === h).length, cC_B = _cuspAinB.filter(c => c.maison_cuspide === h).length;
  let inner = '';
  if (dA) inner += _synSubDirection(isEN ? `What ${esc(persoB)} awakens in ${esc(persoA)}` : `Ce que ${esc(persoB)} éveille chez ${esc(persoA)}`, '#2E5FA3', '#f0f4fb', '#1F3864', dA.llm_text, _hiBinA[h], oC_A, cC_A);
