    const NI = { harmonique: { c: '#059669', i: '●', l: isEN ? 'Harmonious' : 'Harmonique' }, tension: { c: '#dc2626', i: '▲', l: isEN ? 'Tense' : 'Tendu' }, neutre: { c: '#d97706', i: '◆', l: isEN ? 'Neutral' : 'Neutre' } };
