    const t1 = [...(synData.inter_aspects_tier1_b_to_a || []), ...(synData.inter_aspects_tier1_a_to_b || [])];
    const topAsp = [...t1].sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 3);
