const jd  = julianDay(dt.year, dt.month, dt.day, dt.hour);
const prec = precessionDeg(jd);

// ── Calcul des 23 étoiles ─────────────────────────────────────────────────
const output = ETOILES.map(e => {
  const lon = ((e.lon_j2000 + prec) % 360 + 360) % 360;
  const pos = lonToSign(lon);

  // Écart par rapport à la position traditionnelle de référence
  // Calcul sur fullDegree pour éviter les erreurs aux frontières de signes
  const refFull = e.ref_sign_idx * 30 + e.ref_deg;
  let ecart = lon - refFull;
  if (ecart > 180)  ecart -= 360;
  if (ecart < -180) ecart += 360;

  return {
    name:             { fr: e.name_fr, en: e.name_en },
    fullDegree:       pos.fullDegree,
    normDegree:       pos.normDegree,
    sign_index:       pos.sign_index,
    zodiac_sign:      pos.zodiac_sign,
    methode:          "precession_j2000",
    reference:        { signe: e.ref_sign, degre: e.ref_deg, label: e.ref_deg + "\u00b0 " + e.ref_sign },
    ecart_reference:  Math.round(ecart * 10000) / 10000,
    declination_j2000: e.dec_j2000 || null,
    ra_j2000: e.ra_j2000 || null
  };
});

return [{
  json: {
    date:           dateStr,
    julian_day:     Math.round(jd * 1000000) / 1000000,
    precession_deg: Math.round(prec * 10000) / 10000,
    output:         output
  }
}];

