            p += `   Maître du signe de la cuspide : ${seg.maitre.planete}${seg.maitre.retro} en M${seg.maitre.maison} (${seg.maitre.signe}${mHStr})${mHelio}. [NB : ce "Maître" est le ruler du signe ${seg.signe} — à ne PAS confondre avec le Gouverneur du thème ni l'Almutem Figuris]\n`;
            p += `   Aspects du maître : ${getMajorAspectsStr(seg.maitre.planete)}.\n`;
            if (seg.maitre.patron) p += `   Chaîne : ${seg.signe} → M${seg.maitre.maison} → finalité M${seg.maitre.patron.maison} (${seg.maitre.patron.planete}).\n`;
