pSynth += `⛔ TERMINOLOGIE OBLIGATOIRE : ${stats.sectMalefic} = "maléfique tempéré" ou "maléfique de secte". ${stats.contraSectMalefic} = "maléfique hors-secte" ou "maléfique aggravé (contra-secte)". Ne JAMAIS dire "${stats.contraSectMalefic} est le maléfique de ta secte" — c'est FAUX, ${stats.contraSectMalefic} est HORS de la secte ${sectStr.split(" ")[0].toLowerCase()}.\n`;

