        const triplRuler = isDayChart ? TRIPLIC_DAY[kp.sign] : TRIPLIC_NIGHT[kp.sign];
        if (name === triplRuler) almutemScore[name] += 3;
        // Triplicité participante (+1.5) — 3e seigneur Dorothéen, actif quelle que soit la secte
        const triplPart = TRIPLIC_PART_EARLY[kp.sign];
        if (name === triplPart && name !== triplRuler) almutemScore[name] += 1.5;
