        const decanIdx  = Math.min(Math.floor((kp.deg % 30) / 10), 2);
        const faceRuler = CHALDEAN_DECANS[kp.sign]?.[decanIdx];
        if (name === faceRuler) almutemScore[name] += 1;
    });
