// ── C4a : HAYZ (condition de secte optimale) ──
const hayzPlanets = [];
DISPOSITOR_PLANETS.forEach(name => {
    const p = planetes.find(x => x.planet.fr === name); if (!p) return;
    const sign = p.zodiac_sign?.name?.fr;
    const house = getHouseNumber(p.fullDegree);
    const aboveHorizon = [7,8,9,10,11,12].includes(house);
    const isMasculine = MASCULINE_SIGNS.has(sign);
    let inHayz = false, desc = "";
    if (isDayChart && DIURNAL_PLANETS.has(name) && aboveHorizon && isMasculine) {
        inHayz = true; desc = `${name} diurne, au-dessus de l'horizon, en signe masculin (${sign}) de jour — condition de HAYZ parfaite : la planète opère dans son élément naturel avec une efficacité maximale.`;
    } else if (!isDayChart && NOCTURNAL_PLANETS.has(name) && !aboveHorizon && !isMasculine) {
        inHayz = true; desc = `${name} nocturne, sous l'horizon, en signe féminin (${sign}) de nuit — condition de HAYZ parfaite : la planète opère dans son élément naturel avec une efficacité maximale.`;
    }
    if (inHayz) hayzPlanets.push({ planet: name, description: desc });
});

// ── C4b : PLANÈTES ASSIÉGÉES (entre deux maléfiques) ──
const besiegedPlanets = [];
const sortedByDeg = DISPOSITOR_PLANETS
    .map(name => ({ name, deg: planetes.find(x => x.planet.fr === name)?.fullDegree }))
    .filter(p => p.deg !== undefined)
    .sort((a, b) => a.deg - b.deg);
sortedByDeg.forEach((p, idx) => {
    if (MALEFICS_TRAD.has(p.name) || BENEFICS_TRAD.has(p.name)) return;
    const prev = sortedByDeg[(idx - 1 + sortedByDeg.length) % sortedByDeg.length];
    const next = sortedByDeg[(idx + 1) % sortedByDeg.length];
    if (MALEFICS_TRAD.has(prev.name) && MALEFICS_TRAD.has(next.name)) {
        // Vérifier si un bénéfique intercepte le besiegement (atténuation)
        const pDeg = p.deg, prevDeg = prev.deg, nextDeg = next.deg;
        const beneficIntervenes = sortedByDeg.some(bp => {
            if (!BENEFICS_TRAD.has(bp.name)) return false;
            if (prevDeg < nextDeg) return bp.deg > prevDeg && bp.deg < nextDeg;
            return bp.deg > prevDeg || bp.deg < nextDeg;
        });
        const severity = beneficIntervenes ? "ATTÉNUÉE" : "STRICTE";
        besiegedPlanets.push({
            planet: p.name,
            between: [prev.name, next.name],
            severity,
            description: beneficIntervenes
                ? `${p.name} est assiégée entre ${prev.name} et ${next.name}, mais un bénéfique intervient — pression atténuée.`
                : `${p.name} est ASSIÉGÉE entre ${prev.name} et ${next.name} — contrainte, pression, empêchement. L'énergie de ${p.name} est entravée par les deux maléfiques traditionnels.`
        });
    }
});

// ── C4c : VIDE DE COURSE DE LA LUNE ──
let moonVoidOfCourse = null;
if (moon) {
    const moonDeg = moon.fullDegree;
    const moonSign = moon.zodiac_sign?.name?.fr;
    const moonSignEnd = (Math.floor(moonDeg / 30) + 1) * 30;
    const majorAspDegs = [0, 60, 90, 120, 180];
    let hasApplyingAspect = false;
    DISPOSITOR_PLANETS.filter(n => n !== "Lune").forEach(name => {
        const p = planetes.find(x => x.planet.fr === name); if (!p) return;
        majorAspDegs.forEach(aspDeg => {
            const targetDeg = (p.fullDegree + aspDeg) % 360;
            const targetDeg2 = (p.fullDegree - aspDeg + 360) % 360;
            [targetDeg, targetDeg2].forEach(td => {
                if (td > moonDeg && td < moonSignEnd) hasApplyingAspect = true;
            });
        });
    });
    if (!hasApplyingAspect) {
        moonVoidOfCourse = {
            active: true,
            sign: moonSign,
            description: `Lune VIDE DE COURSE en ${moonSign} — la Lune ne forme plus d'aspect majeur appliquant avant de quitter le signe. Indique un tempérament qui fonctionne « hors cadre », par intuition pure plutôt que par connexion directe. Les projets initiés peuvent manquer d'écho immédiat mais mûrissent de façon non conventionnelle.`
        };
    }
}

