    const _vxTanPhi = (-_vxD - Math.sin(_vxRamc) * Math.cos(_VX_EPS)) / Math.sin(_VX_EPS);
    const _vxPhi = Math.atan(_vxTanPhi);                  // latitude géographique (-90..90)
    if (!Number.isFinite(_vxPhi) || Math.abs(_vxPhi) > 89.5 * _VX_RAD) return;
    const _vxRamcOpp = _vxRamc + Math.PI;
    const _vxCoLat = (Math.PI / 2) - _vxPhi;              // co-latitude
    const _vxRad = Math.atan2(Math.cos(_vxRamcOpp), -Math.sin(_vxRamcOpp) * Math.cos(_VX_EPS) - Math.tan(_vxCoLat) * Math.sin(_VX_EPS));
