const eclipseNatal = input.eclipseNatal || null;
let eclipseNatalData = null;
if (eclipseNatal && (eclipseNatal.type || eclipseNatal.eclipse_type || eclipseNatal.typeEclipse)) {
    const eclipseDeg = typeof eclipseNatal.fullDegree === 'number' ? eclipseNatal.fullDegree
                     : typeof eclipseNatal.degree     === 'number' ? eclipseNatal.degree
                     : typeof eclipseNatal.degre      === 'number' ? eclipseNatal.degre
                     : null;
    if (eclipseDeg !== null) {
        const normalizedDeg = ((eclipseDeg % 360) + 360) % 360;
        const eclipseHouse  = getHouseNumber(normalizedDeg);
        const eclipseSign   = signs[Math.floor(normalizedDeg / 30) % 12].fr;
        const eclipseType   = eclipseNatal.type || eclipseNatal.eclipse_type || eclipseNatal.typeEclipse || "Solaire";
        const eclipseAstre  = eclipseNatal.astre || (eclipseType.includes("Lunaire") ? "Lune" : "Soleil");
        const eclipseLabel  =
            `⚡ ÉCLIPSE À LA NAISSANCE (${eclipseType} de ${eclipseAstre}) en ${eclipseSign} à ${(normalizedDeg % 30).toFixed(1)}° — Maison ${eclipseHouse}. ` +
            `Cet individu est né le jour même d'une éclipse : les thèmes de la Maison ${eclipseHouse} sont chargés d'une mission de transformation profonde. ` +
            `Cette éclipse amplifie toutes les lectures de la Maison ${eclipseHouse} et confère une sensibilité karmatique permanente sur ce degré.`;

        if (eclipseHouse >= 1 && eclipseHouse <= 12) {
            prompts[`maison_${eclipseHouse}`] +=
                `\n\n=== ⚡ ÉCLIPSE À LA NAISSANCE ===\n${eclipseLabel}\n` +
                `→ INSTRUCTION : Les thèmes de cette maison doivent être traités comme PRIORITAIRES et AMPLIFIÉS. ` +
                `L'éclipse natale confère une mission, une blessure-catalyseur ou une rupture fondatrice sur ces thèmes. ` +
                `Tout transit futur sur ce degré (${(normalizedDeg % 30).toFixed(1)}° ${eclipseSign}) réactivera cette éclipse natale.`;
        }
        prompts["synthese_globale"] +=
            `\n\n=== ⚡ ÉCLIPSE À LA NAISSANCE ===\n${eclipseLabel}\n` +
            `→ INSTRUCTION : Intégrer cette éclipse natale comme signature karmique centrale du thème. ` +
            `L'individu porte en lui l'archétype de la rupture/transformation dans les thèmes de la Maison ${eclipseHouse}.`;

        eclipseNatalData = {
            type: eclipseType, astre: eclipseAstre, sign: eclipseSign,
            house: eclipseHouse, degree: normalizedDeg, label: eclipseLabel
        };
