// 10. EMPHASE HÉMISPHÉRIQUE & ORIENTATION DU THÈME
// ─────────────────────────────────────────────────────────────────
const coreForHemis = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
let hemisN=0, hemisS=0, hemisE=0, hemisW=0;
coreForHemis.forEach(name => {
    const p = planetes.find(x => x.planet.fr === name); if (!p) return;
    const house = Number(getHouseNumber(p.fullDegree));
    if ([1,2,3,4,5,6].includes(house))    hemisN++; else hemisS++;  // M1-M6 = sous l'horizon (privé/intérieur), M7-M12 = au-dessus (public/extérieur)
    if ([10,11,12,1,2,3].includes(house)) hemisE++; else hemisW++;
});
stats.hemispheres = { "Sous l'horizon (M1-M6)": hemisN, "Au-dessus (M7-M12)": hemisS, Est: hemisE, Ouest: hemisW };

// ─────────────────────────────────────────────────────────────────
// 11. PLANÈTE DOMINANTE (score multi-critères)
// ─────────────────────────────────────────────────────────────────
const dominanceScore = {};
coreForHemis.forEach(name => { dominanceScore[name] = 0; });
angularPlanets.forEach(ap => { if (dominanceScore[ap.planet] !== undefined) dominanceScore[ap.planet] += 3; });
coreForHemis.forEach(name => {
    const p = planetes.find(x => x.planet.fr === name); if (!p) return;
    const dig = getDignity(name, p.zodiac_sign?.name?.fr);
    if (dig === "Domicile")   dominanceScore[name] += 2;
    if (dig === "Exaltation") dominanceScore[name] += 1;
    if (helioConditions[name]?.condition?.includes("CAZIMI")) dominanceScore[name] += 2;
});
coreForHemis.forEach(name => {
    const count = aspects.filter(a => a.isMajor && (a.p1 === name || a.p2 === name)).length;
    dominanceScore[name] += Math.min(count, 5);
});
// Bonus OOB : planète hors limites = énergie exacerbée (+3 pts)
coreForHemis.forEach(name => {
    if (OOB_NAMES_SET.has(name)) dominanceScore[name] += 3;
});
// Bonus Station : planète stationnaire = concentration d'énergie exceptionnelle (+4 pts)
stationaryPlanets.forEach(sp => {
    if (dominanceScore[sp.planet] !== undefined) dominanceScore[sp.planet] += 4;
});
const ascSignForDom = asc ? asc.zodiac_sign?.name?.fr : null;
const chartRulerForDom = ascSignForDom ? signs.find(s => s.fr === ascSignForDom)?.ruler : null;
if (chartRulerForDom && dominanceScore[chartRulerForDom] !== undefined) dominanceScore[chartRulerForDom] += 2;
const chartRulerTradForDom = ascSignForDom ? MAITRES_TRAD_THEME[ascSignForDom] : null;
if (chartRulerTradForDom && chartRulerTradForDom !== chartRulerForDom && dominanceScore[chartRulerTradForDom] !== undefined) dominanceScore[chartRulerTradForDom] += 1;
fiches_maisons.forEach(fm => {
    fm.segments.forEach(seg => {
        if (seg.locataires.length > 0 && seg.maitre?.planete && dominanceScore[seg.maitre.planete] !== undefined)
            dominanceScore[seg.maitre.planete] += 1;
    });
});
const dominanteSorted = Object.entries(dominanceScore).sort((a,b) => b[1] - a[1]);
stats.planete_dominante    = dominanteSorted[0]?.[0] || null;
stats.dominance_scores     = dominanteSorted;

