    asc   ? { name:"ASC",   deg:asc.fullDegree,   sign:asc.zodiac_sign?.name?.fr }   : null,
    sun   ? { name:"Sol",   deg:sun.fullDegree,   sign:sun.zodiac_sign?.name?.fr }   : null,
    moon  ? { name:"Lune",  deg:moon.fullDegree,  sign:moon.zodiac_sign?.name?.fr }  : null,
    planetes.find(p=>p.planet.fr==="Part de Fortune") ? {
