].filter(Boolean);

// Triplicité (Ptolémée/Dorothée) — seigneurs diurnes et nocturnes par élément
// Triplicités Ptolémée/Dorothée — tous les signes d'un même élément partagent les mêmes seigneurs
// Feu: Soleil(J) / Jupiter(N) | Terre: Vénus(J) / Lune(N) | Air: Saturne(J) / Mercure(N) | Eau: Vénus(J) / Mars(N)
const TRIPLIC_DAY = {
    "Bélier":"Soleil", "Lion":"Soleil",    "Sagittaire":"Soleil",
    "Taureau":"Vénus", "Vierge":"Vénus",   "Capricorne":"Vénus",
    "Gémeaux":"Saturne","Balance":"Saturne","Verseau":"Saturne",
    "Cancer":"Vénus",  "Scorpion":"Vénus", "Poissons":"Vénus"
};
const TRIPLIC_NIGHT = {
    "Bélier":"Jupiter","Lion":"Jupiter",   "Sagittaire":"Jupiter",
    "Taureau":"Lune",  "Vierge":"Lune",    "Capricorne":"Lune",
    "Gémeaux":"Mercure","Balance":"Mercure","Verseau":"Mercure",
    "Cancer":"Mars",   "Scorpion":"Mars",  "Poissons":"Mars"
};

const almutemScore = {};
coreForHemis.forEach(name => {
    almutemScore[name] = 0;
    keyPoints.forEach(kp => {
        const dig = getDignity(name, kp.sign);
        if (dig === "Domicile")   almutemScore[name] += 5;
        if (dig === "Exaltation") almutemScore[name] += 4;
        if (dig === "Exil")       almutemScore[name] -= 5;
        if (dig === "Chute")      almutemScore[name] -= 4;
        // Triplicité (+3) — seigneur selon la secte du thème
        const triplRuler = isDayChart ? TRIPLIC_DAY[kp.sign] : TRIPLIC_NIGHT[kp.sign];
        if (name === triplRuler) almutemScore[name] += 3;
        // Triplicité participante (+1.5) — 3e seigneur Dorothéen, actif quelle que soit la secte
        const triplPart = TRIPLIC_PART_EARLY[kp.sign];
        if (name === triplPart && name !== triplRuler) almutemScore[name] += 1.5;
        // Terme égyptien (+2)
        const termRuler = getTermRuler(kp.sign, kp.deg);
        if (name === termRuler) almutemScore[name] += 2;
        // Face / Décan chaldéen (+1)
        const decanIdx  = Math.min(Math.floor((kp.deg % 30) / 10), 2);
        const faceRuler = CHALDEAN_DECANS[kp.sign]?.[decanIdx];
        if (name === faceRuler) almutemScore[name] += 1;
    });
});
const almutemSorted = Object.entries(almutemScore).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]);
stats.almutem_figuris = almutemSorted[0]?.[0] || null;
stats.almutem_scores  = almutemSorted;

