    if (!_vxMc || !_vxAsc || !Number.isFinite(_vxMc.fullDegree) || !Number.isFinite(_vxAsc.fullDegree)) return;
    if (planetes.some(p => (p.planet?.fr || p.planet?.en) === "Vertex")) return;
    const _VX_RAD = Math.PI / 180, _VX_EPS = 23.4393 * _VX_RAD;
    const _vxMcR = _vxMc.fullDegree * _VX_RAD, _vxAscR = _vxAsc.fullDegree * _VX_RAD;
    const _vxRamc = Math.atan2(Math.sin(_vxMcR) * Math.cos(_VX_EPS), Math.cos(_vxMcR));
    const _vxSinAsc = Math.sin(_vxAscR);
    if (Math.abs(_vxSinAsc) < 1e-6) return;               // ASC ≈ 0°/180° (cas quasi impossible) : on s'abstient
