if (tzA?.gmtOffset !== undefined && tzB?.gmtOffset !== undefined) {
  tzMid = ((tzA.gmtOffset + tzB.gmtOffset) / 2) / 3600;
} else if (tzA?.gmtOffset !== undefined) {
  tzMid = tzA.gmtOffset / 3600;
}

const payload = {
  year: midDate.getUTCFullYear(),
  month: midDate.getUTCMonth() + 1,
  date: midDate.getUTCDate(),
  hours: midDate.getUTCHours(),
  minutes: midDate.getUTCMinutes(),
