};

const pad = n => String(n).padStart(2, '0');
const dateDavisonStr = `${pad(midDate.getUTCDate())}/${pad(midDate.getUTCMonth()+1)}/${midDate.getUTCFullYear()} ${pad(midDate.getUTCHours())}H${pad(midDate.getUTCMinutes())}`;

return [{ json: {
  body: JSON.stringify(payload),
  date_davison: dateDavisonStr,
