//            • paragraphes courts, mots-clés en **gras**, "vous" + prénoms
//            • ancre factuelle DÉTERMINISTE riche (anti-hallucination)
//          On ne traduit PLUS les 12 perspectives maison : elles ne sont pas
//          rendues dans le rapport final (code mort) -> 7 appels au lieu de 13.
// SANS dépendance externe (VM n8n : pas de require / process / fs).
// ============================================================================

const reassembled = $input.first()?.json;
if (!reassembled) return [];

const synData = reassembled.synData || {};
const meta = synData.meta || {};

// --- contexte langue / prénoms / typologie ---
const langueRaw = String(meta.langue || 'Français');
const isEN = /^en|angl/i.test(langueRaw);
const persA = (meta.personne_a && (meta.personne_a.prenom || meta.personne_a.nom)) || 'A';
const persB = (meta.personne_b && (meta.personne_b.prenom || meta.personne_b.nom)) || 'B';
const shortName = (full) => String(full || '').trim().split(/\s+/)[0] || full;

// --- GARDE ANTI-HALLUCINATION ÉTOILES FIXES — valence IMPOSÉE ---
// Empêche le contresens type « la bienveillante étoile Algol ».
// D = difficile/épreuve · M = double tranchant · B = bénéfique.
const STAR_VALENCE = {
  "Algol":"D","Pléiades":"D","Alcyone":"D","Vindemiatrix":"D","Scheat":"D","Zubenelgenubi":"D","Facies":"D","Lesath":"D","Praesepe":"D","Asellus Australis":"D",
  "Aldébaran":"M","Régulus":"M","Antarès":"M","Bételgeuse":"M","Castor":"M","Pollux":"M","Procyon":"M","Bellatrix":"M","Markab":"M","Asellus Borealis":"M",
  "Sirius":"B","Spica":"B","Véga":"B","Wega":"B","Fomalhaut":"B","Rigel":"B","Canopus":"B","Arcturus":"B","Deneb Algedi":"B","Zubeneschamali":"B","Achernar":"B","Deneb":"B","Mirach":"B","Mirfak":"B","Capella":"B","Alphecca":"B","Toliman":"B","Polis":"B","Ascella":"B","Altaïr":"B","Sadalmelik":"B",
};
const STAR_VALENCE_TXT = {
  fr: { D:"DIFFICILE (épreuve / danger — tu peux nommer la force qui NAÎT de l'épreuve, mais JAMAIS la dire « bienveillante », « protectrice », « douce » ni « chanceuse », et jamais « loin des mythes » : l'épreuve doit rester nommée)", M:"À DOUBLE TRANCHANT (don ET risque — nomme les deux)", B:"BÉNÉFIQUE (favorable, chance/talent)" },
  en: { D:"DIFFICULT (trial / danger — name the strength BORN from the ordeal if you wish, but NEVER call it \"kindly\", \"protective\", \"gentle\" or \"lucky\", and never \"beyond the myths\": the ordeal must stay named)", M:"DOUBLE-EDGED (gift AND risk — name both)", B:"BENEFIC (favourable, luck/talent)" },
};
function starValenceLines(names, en) {
  const L = en ? 'en' : 'fr';
  const uniq = [...new Set((names || []).map(n => String(n || '').trim()).filter(Boolean))].filter(n => STAR_VALENCE[n]);
  if (!uniq.length) return '';
  const head = en ? '- IMPOSED FIXED-STAR NATURES (NEVER contradict):' : '- NATURES IMPOSÉES DES ÉTOILES FIXES (à ne JAMAIS contredire) :';
  return '\n' + head + '\n' + uniq.map(n => `  • ${n} : ${STAR_VALENCE_TXT[L][STAR_VALENCE[n]]}`).join('\n');
}

// --- Mode d'adresse (miroir du Super noeud Syn) ---------------------------------
// Le rapport final est CENTRÉ sur la personne A (le destinataire de l'analyse).
// On l'adresse selon personne_a.consigne_redaction (Tu / Vous / Il / Elle) et on
// parle TOUJOURS de la personne B à la troisième personne (pronom_tiers / genre).
const pA = meta.personne_a || {};
const pB = meta.personne_b || {};
const consigneA = String(pA.consigne_redaction || 'Tu');
const pronomB = String(pB.pronom_tiers || (String(pB.genre || 'F').toUpperCase() === 'M' ? 'Il' : 'Elle'));
const pronomA3 = String(pA.pronom_tiers || (String(pA.genre || 'M').toUpperCase() === 'F' ? 'Elle' : 'Il'));
const aIsThird = /^(il|elle)$/i.test(consigneA);
const enYouOrThird = aIsThird ? (/^elle$/i.test(consigneA) ? 'she' : 'he') : 'you';
const enPronB = /^elle$/i.test(pronomB) ? 'she' : 'he';

const aIsVous = /^vous$/i.test(consigneA);
const addressDirective = isEN
  ? (aIsThird
      ? `Refer to ${persA} in the third person ("${enYouOrThird}") and to ${persB} in the third person ("${enPronB}"). The story is delivered ABOUT ${persA} (the recipient): it is centered on ${persA}'s experience of the relationship with ${persB}. Never address anyone directly, and never use "they as a couple" wording that blends the two.`
      : `Address ${persA} directly using "you" — ${persA} is the SOLE recipient of the report; the story is centered on ${persA}'s experience of the relationship with ${persB}. ALWAYS refer to ${persB} in the third person ("${enPronB}"). NEVER use "the two of you / you both / your couple", not even for shared things: write "your exchanges with ${persB}", "between you and ${persB}", "your relationship with ${persB}". Never address ${persB} directly.`)
  : (aIsThird
      ? `Parle de ${persA} à la troisième personne ("${consigneA}") et de ${persB} à la troisième personne ("${pronomB}"). Le récit est livré À PROPOS de ${persA} (le destinataire) : il est centré sur le vécu de ${persA} dans sa relation avec ${persB}. Ne t'adresse jamais directement à quiconque, et n'emploie jamais de tournure qui fond les deux en un « ils/vous ».`
      : aIsVous
        ? `Adresse-toi directement à ${persA} en le VOUVOYANT (vous de politesse au SINGULIER, une seule personne) : ${persA} est le SEUL destinataire du rapport ; le récit est centré sur le vécu de ${persA} dans sa relation avec ${persB}. Parle TOUJOURS de ${persB} à la troisième personne ("${pronomB}"). N'emploie JAMAIS « vous deux / entre vous / votre couple » pour désigner les deux ensemble ; même pour ce qui est partagé, écris « vos échanges avec ${persB} », « entre vous et ${persB} », « votre relation avec ${persB} ». Ne t'adresse JAMAIS à ${persB}.`
        : `Adresse-toi directement à ${persA} en le TUTOYANT (tu, ton/ta/tes, toi) : ${persA} est le SEUL destinataire du rapport ; le récit est centré sur le vécu de ${persA} dans sa relation avec ${persB}. Parle TOUJOURS de ${persB} à la troisième personne ("${pronomB}"). N'emploie JAMAIS vous/votre/vos ni « vous deux / entre vous » ; même pour ce qui est partagé, écris « tes échanges avec ${persB} », « entre toi et ${persB} », « ta relation avec ${persB} ». Ne t'adresse JAMAIS à ${persB}.`);

// --- extras enrichis (compat élémentaire + aspects), best-effort ---
let elementCompat = synData.element_compatibility || null;
try { if (!elementCompat) elementCompat = $('Super noeud Syn').first().json.element_compatibility || null; } catch (e) {}

// ============================================================================
// 1) ANCRE FACTUELLE RICHE (spine) — interne, anti-hallucination
// ============================================================================
function buildSynSpine() {
  const L = [];
  const gd = synData.global_score_detail || {};
  const band = gd.qualitative_band || {};
  const gscore = (synData.global_score != null) ? synData.global_score : (gd.harmony != null ? gd.harmony : null);

  L.push(isEN
    ? `RELATIONSHIP: ${persA} & ${persB} — type: ${meta.typoConfig?.label_en || meta.typoConfig?.label_fr || meta.typologie || 'relationship'}.`
    : `LIEN : ${persA} & ${persB} — type : ${meta.typoConfig?.label_fr || meta.typologie || 'relation'}.`);

  if (gscore != null) {
    const bandTxt = (isEN ? band.band_en : band.band) || '';
    const bandDesc = (isEN ? band.desc_en : band.desc) || '';
    L.push(isEN
      ? `- Overall harmony: ${gscore}/100${bandTxt ? ' — ' + bandTxt : ''}${bandDesc ? ' (' + bandDesc + ')' : ''}.`
      : `- Harmonie globale : ${gscore}/100${bandTxt ? ' — ' + bandTxt : ''}${bandDesc ? ' (' + bandDesc + ')' : ''}.`);
  }
  if (gd.intensity != null) L.push(isEN ? `- Bond intensity: ${gd.intensity}/100.` : `- Intensité du lien : ${gd.intensity}/100.`);
  if (elementCompat && (elementCompat.summary_fr || elementCompat.summary_en)) {
    L.push(isEN
      ? `- Elemental compatibility: ${elementCompat.summary_en || elementCompat.summary_fr}.`
      : `- Compatibilité élémentaire : ${elementCompat.summary_fr || elementCompat.summary_en}.`);
  }

  // Aspects relationnels marquants (signature_aspects, déjà curés et scorés)
  const sigs = (synData.signature_aspects || []).filter(a => a && a.pair).slice().sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 8);
  if (sigs.length) {
    const natFR = { tension: 'tension', harmonie: 'harmonie', harmony: 'harmonie', support: 'soutien', conjonction: 'fusion' };
    const natEN = { tension: 'tension', harmonie: 'harmony', harmony: 'harmony', support: 'support', conjonction: 'fusion' };
    L.push(isEN ? `- Strongest links between you:` : `- Liens les plus marquants entre vous :`);
    sigs.forEach(a => {
      const nat = (isEN ? natEN : natFR)[String(a.nature || '').toLowerCase()] || a.nature || '';
      const who = shortName(a.source_personne);
      L.push(`  • ${a.pair}${nat ? ' (' + nat + ')' : ''}${who ? (isEN ? ' — carried by ' + who : ' — porté par ' + who) : ''}`);
    });
  }

  // Grandes figures de la relation
  const cfgs = (synData.synastric_configurations || []).map(c => c.type || c.name).filter(Boolean);
  if (cfgs.length) L.push(isEN ? `- Major patterns: ${[...new Set(cfgs)].join(', ')}.` : `- Grandes figures du lien : ${[...new Set(cfgs)].join(', ')}.`);

  // Étoiles fixes notables (≤ 4, précision forte d'abord)
  const starMatches = [...(synData.etoile_matches_a || []), ...(synData.etoile_matches_b || [])]
    .filter(e => e && e.etoile && !e.isAngle)
    .sort((a, b) => (String(b.precision || '').includes('forte') ? 1 : 0) - (String(a.precision || '').includes('forte') ? 1 : 0))
    .slice(0, 4);
  const stars = starMatches.map(e => `${e.etoile}${e.planete ? ' (' + e.planete + ')' : ''}`);
  if (stars.length) {
    L.push(isEN ? `- Notable fixed stars: ${stars.join(', ')}.` : `- Étoiles fixes notables : ${stars.join(', ')}.`);
    const vl = starValenceLines(starMatches.map(e => e.etoile), isEN);
    if (vl) L.push(vl.replace(/^\n/, ''));
  }

  return L.join('\n');
}
const SPINE = buildSynSpine();

// ============================================================================
// 2) DÉCOUPAGE DE LA SYNTHÈSE EN CHAPITRES (## titre)
// ============================================================================
function splitSynthChapters(text) {
  const lines = String(text || '').split('\n');
  const chapters = [];
  let cur = null;
  for (const ln of lines) {
    const hm = ln.match(/^#{1,3}\s+(.+?)\s*#*\s*$/);
    if (hm && !/^#{1,3}\s*$/.test(ln)) {
      if (cur) chapters.push(cur);
      cur = { title: hm[1].replace(/\*/g, '').replace(/^\d+\.\s*/, '').trim(), body: [] };
    } else if (cur) {
      cur.body.push(ln);
    }
  }
  if (cur) chapters.push(cur);
  return chapters
    .map(c => ({ title: c.title, body: c.body.join('\n').trim() }))
    .filter(c => c.title || c.body);
}

// ============================================================================
// 3) PROMPT DE RE-TISSAGE PAR CHAPITRE (auto-porté, miroir THEME chapRules)
// ============================================================================
function buildChapterPrompt(chap, idx, total) {
  const isLast = idx === total - 1;
  const A = persA, B = persB;

  if (isEN) {
    const titleRule = `TITLE: start your answer with the chapter title on a single line prefixed by "# " (one hash). Keep the SAME theme as the source title "${chap.title}" (preserve its key words) but adapt its wording to the address mode above. Then a blank line, then the body.`;
    const structure = isLast
      ? `STRUCTURE (this is the CLOSING chapter):
- ${titleRule}
- Do NOT write any "overall harmony score" line or numeric score: it is rendered separately. Start the body directly with the sub-heading below.
- Then a "## The essentials" sub-heading (1-2 short paragraphs summing up the bond).
- Then a "## Advice" sub-heading with 3 to 5 concrete, actionable tips as a markdown bullet list ("- ").
- No "## In practice" for this chapter.`
      : `STRUCTURE (mandatory):
- ${titleRule}
- In the body, do NOT repeat the chapter title.
- Split into 2 or 3 content SUB-HEADINGS, short and evocative, in markdown "## " (e.g. "## A magnetic pull"). Under each, 1 to 2 short paragraphs.
- End with a final "## In practice" sub-heading: 2-3 very concrete sentences, an embodied tip.
- NEVER use "### ". All sub-headings use "## ".`;
    return `GOAL: rewrite the chapter "${chap.title}" of the relationship analysis delivered to ${A} (about ${A}'s relationship with ${B}), making it vivid, embodied and crystal-clear for a reader who knows nothing about astrology. You do NOT summarize: you re-weave the SAME substance into pleasant prose.

ADDRESS (mandatory): ${addressDirective}

FACTUAL ANCHOR (facts of the ${A} & ${B} bond — invent nothing, never change who influences whom):
${SPINE}

SOURCE (analysis to re-weave — keep ALL the substance, drop no idea, but restructure the FORM; if the source addresses ${B} directly, convert it to the third person):
---
${chap.body}
---

${structure}

B2C MAGAZINE STYLE:
- SHORT paragraphs (2-3 sentences max), separated by a blank line.
- Put 2 to 3 strong keywords per paragraph in **bold** (emotions, dynamics, planet names) — NEVER a whole sentence, NEVER a heading.
- Whenever you list more than two ideas/tips, switch to a markdown bullet list ("- ").

FIDELITY:
- ALWAYS preserve who influences whom (the direction of the bond). Never change a planet's sign or life area.
- NO jargon (trine, square, cusp, orb, overlay, lot, midpoint, dignity, reception, antiscia, parallel, OOB, Davison, composite…): translate it into lived meaning. Keep planet, sign and fixed-star names.
- Name each fixed star by its EXACT proper name. Invent no fact beyond the SOURCE and ANCHOR. Reply in ENGLISH.
- FIXED STARS — VALENCE (critical, anti-nonsense): respect each star's TRUE nature. NEVER write that a star of ordeal (Algol, Scheat, Vindemiatrix, Zubenelgenubi, Pleiades/Alcyone, Lesath, Facies, Praesepe, Asellus Australis…) is "kindly", "protective", "gentle", "lucky" or "harmless", and never "beyond the myths". You may evoke the strength born from the trial, never deny the trial. If a star appears in the IMPOSED FIXED-STAR NATURES list, follow that valence to the letter.`;
  }

  const titleRule = `TITRE : commence ta réponse par le titre du chapitre sur une seule ligne préfixée de « # » (un seul dièse). Garde le MÊME thème que le titre source « ${chap.title} » (conserve ses mots-clés) mais adapte sa formulation au mode d'adresse ci-dessus. Ensuite une ligne vide, puis le corps.`;
  const structure = isLast
    ? `STRUCTURE (c'est le chapitre de CLÔTURE) :
- ${titleRule}
- N'écris AUCUNE ligne « Note globale d'harmonie » ni aucun score chiffré : c'est rendu séparément. Démarre le corps directement par le sous-titre ci-dessous.
- Puis un sous-titre « ## L'essentiel » (1-2 paragraphes courts qui résument le lien).
- Puis un sous-titre « ## Conseils » avec 3 à 5 conseils concrets et actionnables en liste à puces (« - »).
- Pas de « ## En pratique » pour ce chapitre.`
    : `STRUCTURE (obligatoire) :
- ${titleRule}
- Dans le corps, ne répète PAS le titre du chapitre.
- Découpe en 2 ou 3 SOUS-TITRES de contenu, courts et évocateurs, en markdown « ## » (ex : « ## Un magnétisme immédiat »). Sous chacun, 1 à 2 paragraphes courts.
- Termine par un dernier sous-titre « ## En pratique » : 2 à 3 phrases très concrètes, un conseil incarné.
- N'utilise JAMAIS « ### ». Tous les sous-titres en « ## ».`;

  return `OBJECTIF : ré-écris le chapitre « ${chap.title} » de l'analyse relationnelle livrée à ${A} (sur sa relation avec ${B}), en le rendant vivant, incarné et limpide pour un lecteur qui n'y connaît rien en astrologie. Tu ne résumes pas : tu re-tisses le MÊME fond en une prose agréable à lire.

ADRESSE (impératif) : ${addressDirective}

ANCRAGE FACTUEL (faits du lien ${A} & ${B} — n'invente rien, ne change jamais qui influence qui) :
${SPINE}

SOURCE (analyse à re-tisser — garde TOUT le fond, ne supprime aucune idée, mais restructure la FORME ; si la source s'adresse directement à ${B}, convertis-la à la troisième personne) :
---
${chap.body}
---

${structure}

STYLE MAGAZINE B2C :
- Paragraphes COURTS (2-3 phrases max), séparés par une ligne vide.
- Mets en **gras** 2 à 3 mots-clés forts par paragraphe (émotions, dynamiques, noms de planètes) — JAMAIS une phrase entière, JAMAIS un titre.
- Dès que tu énumères plus de deux idées/conseils, passe en liste à puces markdown (« - »).

FIDÉLITÉ :
- Préserve TOUJOURS qui influence qui (la direction du lien). Ne change jamais le signe ni le secteur d'une planète.
- AUCUN jargon (trigone, carré, cuspide, orbe, overlay, lot, midpoint, dignité, réception, antiscia, parallèle, hors-limites, Davison, composite…) : traduis-le en sens vécu. Garde les noms de planètes, de signes et d'étoiles fixes.
- Cite chaque étoile fixe par son nom propre EXACT. N'invente aucun fait hors de la SOURCE et de l'ANCRAGE. Réponds en FRANÇAIS.
- ÉTOILES FIXES — VALENCE (capitale, anti-contresens) : respecte la nature RÉELLE de chaque étoile. N'écris JAMAIS qu'une étoile d'épreuve (Algol, Scheat, Vindemiatrix, Zubenelgenubi, Pléiades/Alcyone, Lesath, Facies, Praesepe, Asellus Australis…) est « bienveillante », « protectrice », « douce », « chanceuse » ou « sans danger », et jamais « loin des mythes ». Tu peux évoquer la force NÉE de l'épreuve, jamais nier l'épreuve. Si une étoile figure dans la liste NATURES IMPOSÉES DES ÉTOILES FIXES, suis sa valence à la lettre.`;
}

// ============================================================================
// 4) ÉMISSION DES ITEMS (1 par chapitre) — schéma compatible Reassemble Trad v4
// ============================================================================
const synthText = (reassembled.synthese && reassembled.synthese.llm_text) || '';
const chapters = splitSynthChapters(synthText);
if (!chapters.length) return [];

const items = chapters.map((chap, i) => ({
  json: {
    key: `synthese_chap_${i + 1}`,
    category: 'synthese_chapter',
    chapter_index: i,
    titre: chap.title,
    label: chap.title,
    house: 0,
    score: null,
    is_principale: false,
    original_text: chap.body,
    prompt_text: buildChapterPrompt(chap, i, chapters.length),
  },
}));

return items;

// ============================================================================
// REASSEMBLE TRAD SYN v4.0 — RÉCIT (miroir THEME PREPROD)
// ----------------------------------------------------------------------------
// Reconstruit la synthèse re-tissée à partir des chapitres traduits 1-par-1.
// Nouveau format : synthese.chapters = [{ title, body }] (le générateur final
// rend chaque chapitre en cartouche numéroté + punchlines "## " + "## En pratique").
// Conserve synthese.llm_text (rétro-compat) et synData (le générateur en a besoin).
// perspective_a/b ne sont plus traduites (code mort dans le rapport final).
// ============================================================================

const items = $input.all();

let originalItems = [];
try { originalItems = $('1. Découpage SYN Trad').all(); } catch (e) {}

let synDataPassThrough = {};
try { synDataPassThrough = $('Reassemble SYN').first()?.json?.synData || {}; } catch (e) {
  try { synDataPassThrough = $('Super noeud Syn').first()?.json || {}; } catch (e2) {}
}

const result = {
  perspective_a: {},
  perspective_b: {},
  synthese: null,
  synData: synDataPassThrough,
  _meta: { total_items: items.length, total_originals: originalItems.length, errors: [], translated: 0 },
};

if (items.length !== originalItems.length) {
  result._meta.warning = `Attendu ${originalItems.length} traductions, reçu ${items.length}`;
}

const chapterBucket = [];

items.forEach((item, idx) => {
  if (item.json?.error || item.json?.errorMessage) {
    result._meta.errors.push({ idx, error: item.json?.errorMessage || item.json?.error });
    return;
  }
  let translated = item.json?.output || item.json?.text || '';
  if (!translated || String(translated).includes('skipped')) return;
  translated = String(translated).trim();

  const orig = originalItems[idx]?.json || {};
  const key = orig.key || '';
  if (!key) { result._meta.errors.push({ idx, error: 'Aucune clé originale' }); return; }
  result._meta.translated++;

  if (key.startsWith('synthese_chap_') || orig.category === 'synthese_chapter') {
    // Le Traducteur préfixe le corps par un titre adapté à l'adresse « # Titre »
    // (un seul dièse). On l'extrait comme titre de chapitre et on le retire du
    // corps (sinon mdRecit le rendrait en punchline). Fallback : titre source.
    let body = translated;
    let title = orig.titre || orig.label || '';
    const lines = body.split('\n');
    let p = 0;
    while (p < lines.length && !lines[p].trim()) p++;
    const tm = lines[p] && lines[p].match(/^#\s+(.+?)\s*#*\s*$/);
    if (tm) {
      title = tm[1].replace(/\*/g, '').trim();
      lines.splice(0, p + 1);
      body = lines.join('\n').replace(/^\s+/, '');
    }
    chapterBucket.push({
      index: (orig.chapter_index != null) ? orig.chapter_index : idx,
      title,
      body,
    });
  } else if (key === 'synthese') {
    // rétro-compat (ancien format à 1 bloc)
    result.synthese = { label: orig.label || 'Synthèse', llm_text: translated };
  } else if (key.startsWith('perspective_a_')) {
    const h = key.replace('perspective_a_', '');
    result.perspective_a[h] = { label: orig.label || '', llm_text: translated, house: orig.house, score: orig.score, is_principale: orig.is_principale };
  } else if (key.startsWith('perspective_b_')) {
    const h = key.replace('perspective_b_', '');
    result.perspective_b[h] = { label: orig.label || '', llm_text: translated, house: orig.house, score: orig.score, is_principale: orig.is_principale };
  }
});

if (chapterBucket.length) {
