// ==========================================
// REASSEMBLE SYN LLM v3.0
// Rassemble les 13 résultats LLM parallèles
// en structure exploitable pour les rapports HTML
// Robustifié : gestion erreurs agents, validation
// ==========================================

const allItems = $input.all();
const prepData = $('Super noeud Syn').first()?.json || {};

let synDataRef = prepData._synRef || {};
if (!synDataRef.meta) {
    try { synDataRef = $('5. Calcul SYN').first()?.json || {}; } catch(e) {
        try { synDataRef = $('Calcul SYN').first()?.json || {}; } catch(e2) {}
    }
}

const result = {
    perspective_a: {},
    perspective_b: {},
    synthese: null,
    synData: synDataRef,
    meta: {
        total_prompts: allItems.length,
        total_active: 0,
        total_errors: 0,
        total_skipped: 0,
        errors: [],
        timestamp: new Date().toISOString()
    }
};

const slotKeys = [
    ...Array.from({length:6}, (_,i) => ({key: `slot_a_${i+1}`, dir: 'perspective_a'})),
    ...Array.from({length:6}, (_,i) => ({key: `slot_b_${i+1}`, dir: 'perspective_b'})),
    {key: 'slot_synth', dir: 'synthese'}
];

if (allItems.length !== slotKeys.length) {
    result.meta.warning = `Attendu ${slotKeys.length} items, reçu ${allItems.length} — vérifier les agents LLM`;
}

for (let idx = 0; idx < allItems.length && idx < slotKeys.length; idx++) {
    const item = allItems[idx];
    const slot = slotKeys[idx];
    const slotData = prepData[slot.key];
    if (!slotData || !slotData.active) {
        result.meta.total_skipped++;
        continue;
    }

    if (item.json?.error || item.json?.errorMessage) {
        result.meta.total_errors++;
        result.meta.errors.push({
            slot: slot.key, house: slotData.house, label: slotData.label,
            error: item.json?.errorMessage || item.json?.error || 'Agent LLM failure'
        });
        continue;
    }

    const llmText = item.json?.output || item.json?.text || item.json?.response || '';
    if (!llmText || llmText.includes('skipped') || llmText.includes('\"skipped\"')) {
        result.meta.total_skipped++;
        continue;
    }

    result.meta.total_active++;

    if (slot.dir === 'synthese') {
        result.synthese = {
            label: slotData.label,
            llm_text: llmText
        };
    } else {
        result[slot.dir][slotData.house] = {
            house: slotData.house,
            label: slotData.label,
            score: slotData.score,
            is_principale: slotData.is_principale,
            llm_text: llmText
        };
    }
}

return [{ json: result }];

