function pickPdfBinary(item) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    if (!b) continue;
    const mime = String(b.mimeType || "").toLowerCase();
    const ext = String(b.fileExtension || "").toLowerCase();
    if (mime.includes("pdf") || ext === "pdf") return b;
  }
  const keys = Object.keys(bin);
  if (keys.length) return bin[keys[0]];
  return null;
}

function normName(s) {
  return String(s || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "");
}

function bucketForFileName(fileName) {
  const n = normName(fileName);
  if (n.includes("rapport technique synastrie") || n.includes("synastry technical report")) return "tech";
  if (n.includes("donnees techniques synastrie") || n.includes("synastry technical data")) return "donnees";
  if ((n.includes("rapport synastrie") || n.includes("synastry report")) && !n.includes("technique") && !n.includes("technical")) return "main";
  return null;
}

